export enum EnvironmentType {
  BEDROOM = '卧室',
  DINING_ROOM = '家庭餐厅',
  OUTDOOR_PICNIC = '户外野餐',
  BATHROOM = '卫生间',
  LIVING_ROOM = '客厅',
  OFFICE = '办公室',
  STUDIO = '专业摄影棚',
  CAFE = '精品咖啡馆'
}

export enum SceneStyle {
  MODERN_LUXURY = '现代奢华',
  ZEN_MINIMALIST = '禅意极简',
  C4D_GEOMETRIC = 'C4D 3D渲染',
  WINDOW_LIGHT = '自然窗光',
  WARM_BOKEH = '温馨灯影',
  BLACK_GOLD = '黑金质感',
  CHAOZHOU_RETRO = '潮汕复古'
}

export enum ImageSize {
  SIZE_1K = '1K',
  SIZE_2K = '2K',
  SIZE_4K = '4K'
}

export interface GenerationConfig {
  environment: EnvironmentType;
  style: SceneStyle;
  customPrompt: string;
  isPro: boolean;
  size: ImageSize;
  addReference: boolean;
  cleanProduct: boolean;
  mode: 'UPLOAD' | 'AI_GEN';
  productPrompt: string;
  batchCount: number;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

export interface GenerationResult {
  originalUrl: string;
  results: string[]; // 改为数组支持批量
  id: string;
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { SceneStyle, EnvironmentType, ImageSize } from "./types";

const getAIClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

/**
 * 方案 B：生成原始产品图
 */
export const generateOriginalProduct = async (
  productDescription: string,
  size: ImageSize = ImageSize.SIZE_1K
): Promise<string> => {
  const ai = getAIClient();
  const prompt = `
    TASK: Generate a professional commercial product photograph.
    SUBJECT: ${productDescription}.
    STYLE: Clean, high-end, studio lighting. 
    BACKGROUND: Pure white or neutral minimalist studio background. 
    QUALITY: 8k, sharp focus, commercial photography quality.
    COMPOSITION: Centered, full view of the product.
  `;

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: { parts: [{ text: prompt }] },
    config: {
      imageConfig: { aspectRatio: "1:1", imageSize: size }
    }
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  throw new Error("未能生成产品图");
};

export const replaceBackground = async (
  base64Image: string,
  environment: EnvironmentType,
  style: SceneStyle,
  customPrompt: string,
  isPro: boolean = false,
  size: ImageSize = ImageSize.SIZE_1K,
  addReference: boolean = false,
  cleanProduct: boolean = false
): Promise<string> => {
  const ai = getAIClient();
  const modelName = isPro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

  const envPrompts: Record<string, string> = {
    [EnvironmentType.BEDROOM]: "in a cozy, high-end bedroom setting, perhaps on a bedside table.",
    [EnvironmentType.DINING_ROOM]: "on a sophisticated dining table with elegant dinnerware.",
    [EnvironmentType.OUTDOOR_PICNIC]: "in a lush green outdoor garden on a picnic cloth.",
    [EnvironmentType.BATHROOM]: "in a clean, modern luxury bathroom on a marble vanity.",
    [EnvironmentType.LIVING_ROOM]: "in a designer living room on a coffee table.",
    [EnvironmentType.OFFICE]: "in a high-tech modern office on a polished desk.",
    [EnvironmentType.STUDIO]: "in a professional clean commercial photography studio.",
    [EnvironmentType.CAFE]: "in a trendy urban boutique cafe on a round wooden table."
  };

  const stylePrompts: Record<string, string> = {
    [SceneStyle.MODERN_LUXURY]: "High-end luxury aesthetics, marble textures, crisp look.",
    [SceneStyle.ZEN_MINIMALIST]: "Soft, peaceful Zen atmosphere, wood and stone elements.",
    [SceneStyle.C4D_GEOMETRIC]: "Professional 3D C4D render style, geometric shapes.",
    [SceneStyle.WINDOW_LIGHT]: "Soft natural morning sunlight through a window, airy feel.",
    [SceneStyle.WARM_BOKEH]: "Cinematic depth of field with golden hour bokeh.",
    [SceneStyle.BLACK_GOLD]: "Moody dark aesthetic, premium black slate, gold accents.",
    [SceneStyle.CHAOZHOU_RETRO]: "Nostalgic atmosphere with traditional Southern Chinese architecture elements."
  };

  const cleaningPrompt = cleanProduct 
    ? "PRODUCT RETOUCHING: Digitally clean the product, remove dust and fingerprints."
    : "";

  const finalPrompt = `
    TASK: PRODUCT RE-STYLING. Keep the product from the image exactly the same.
    ${cleaningPrompt}
    LOCATION: Place it ${envPrompts[environment]}.
    STYLE: ${stylePrompts[style]}.
    USER DETAIL: ${customPrompt}
    QUALITY: Commercial photography, perfect perspective and shadows.
  `;

  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Image.includes(',') ? base64Image.split(',')[1] : base64Image,
    },
  };

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [imagePart, { text: finalPrompt }] },
    config: isPro ? {
      imageConfig: { aspectRatio: "1:1", imageSize: size }
    } : undefined
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("未返回图像数据");
};

import React, { useState, useRef } from 'react';
import { 
  Upload, 
  Sparkles, 
  Download, 
  MessageSquare, 
  X, 
  ChevronRight,
  RefreshCw,
  LayoutGrid,
  Home,
  Palette,
  Wand2,
  Box,
  Image as ImageIcon,
  CheckCircle2
} from 'lucide-react';
import { SceneStyle, EnvironmentType, ImageSize, GenerationConfig, ChatMessage, GenerationResult } from './types';
import { replaceBackground, generateOriginalProduct } from './geminiService';
import { GoogleGenAI } from '@google/genai';

const App: React.FC = () => {
  const [selectedFile, setSelectedFile] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);
  const [config, setConfig] = useState<GenerationConfig>({
    environment: EnvironmentType.DINING_ROOM,
    style: SceneStyle.WINDOW_LIGHT,
    customPrompt: '',
    isPro: true,
    size: ImageSize.SIZE_1K,
    addReference: true,
    cleanProduct: false,
    mode: 'UPLOAD',
    productPrompt: '一套极简主义风格的白色骨瓷茶具',
    batchCount: 3
  });

  const [showChat, setShowChat] = useState(false);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isChatting, setIsChatting] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setSelectedFile(event.target?.result as string);
        setResult(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    setIsProcessing(true);
    try {
      let baseImage = selectedFile;

      // 如果是 AI 生成模式
      if (config.mode === 'AI_GEN') {
        baseImage = await generateOriginalProduct(config.productPrompt, config.size);
        setSelectedFile(baseImage); // 更新预览图
      }

      if (!baseImage) {
        alert("请先上传图片或描述产品");
        return;
      }

      // 批量生成
      const tasks = Array.from({ length: config.batchCount }).map(() => 
        replaceBackground(
          baseImage!,
          config.environment,
          config.style,
          config.customPrompt,
          config.isPro,
          config.size,
          config.addReference,
          config.cleanProduct
        )
      );

      const resultUrls = await Promise.all(tasks);

      setResult({
        originalUrl: baseImage,
        results: resultUrls,
        id: Date.now().toString()
      });
    } catch (error: any) {
      console.error("生成失败:", error);
      alert("生成失败，请检查网络或 API 配置。");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSendMessage = async () => {
    if (!chatInput.trim()) return;
    const userMsg: ChatMessage = { role: 'user', text: chatInput };
    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatting(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const chat = ai.chats.create({
        model: 'gemini-3-pro-preview',
        config: { systemInstruction: "你是一位视觉工作室专家。请用中文回答。" }
      });
      const response = await chat.sendMessage({ message: chatInput });
      const modelMsg: ChatMessage = { role: 'model', text: response.text || '抱歉。' };
      setChatMessages(prev => [...prev, modelMsg]);
    } catch (error) {
      console.error("对话错误:", error);
    } finally {
      setIsChatting(false);
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#080808] text-white selection:bg-indigo-500/30 font-sans">
      {/* 侧边栏 */}
      <aside className="w-full md:w-[400px] border-r border-white/5 bg-[#0c0c0c] p-8 flex flex-col gap-6 overflow-y-auto">
        <header className="flex items-center gap-4 mb-2">
          <div className="p-2.5 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-2xl shadow-lg">
            <Sparkles className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="font-bold text-xl tracking-tight">崇正视觉 Pro</h1>
            <p className="text-[10px] text-white/30 uppercase tracking-[0.2em]">Batch & AI Generation</p>
          </div>
        </header>

        {/* 模式切换 */}
        <section className="bg-white/5 p-1 rounded-2xl flex gap-1">
          <button 
            onClick={() => setConfig({...config, mode: 'UPLOAD'})}
            className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all ${config.mode === 'UPLOAD' ? 'bg-indigo-600 text-white shadow-lg' : 'text-white/40 hover:text-white/60'}`}
          >实拍上传</button>
          <button 
            onClick={() => setConfig({...config, mode: 'AI_GEN'})}
            className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all ${config.mode === 'AI_GEN' ? 'bg-indigo-600 text-white shadow-lg' : 'text-white/40 hover:text-white/60'}`}
          >AI 创作产品</button>
        </section>

        {/* 输入区 */}
        {config.mode === 'UPLOAD' ? (
          <section className="space-y-4">
            <div className="flex items-center gap-2">
               <Upload className="w-3 h-3 text-indigo-400" />
               <label className="text-[10px] font-black text-white/40 uppercase tracking-widest">上传产品照片</label>
            </div>
            <div className={`relative group cursor-pointer border-2 border-dashed ${selectedFile ? 'border-indigo-500/50 bg-indigo-500/5' : 'border-white/5 bg-white/[0.02]'} rounded-3xl aspect-square flex items-center justify-center overflow-hidden`}>
              {selectedFile ? (
                <img src={selectedFile} alt="Preview" className="w-full h-full object-contain p-4" />
              ) : (
                <div className="text-center p-6"><Upload className="w-8 h-8 text-white/20 mx-auto mb-2" /></div>
              )}
              <input type="file" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" />
            </div>
          </section>
        ) : (
          <section className="space-y-4">
            <div className="flex items-center gap-2">
               <Box className="w-3 h-3 text-indigo-400" />
               <label className="text-[10px] font-black text-white/40 uppercase tracking-widest">描述你想生成的产品</label>
            </div>
            <textarea 
              value={config.productPrompt}
              onChange={(e) => setConfig({...config, productPrompt: e.target.value})}
              placeholder="例如：潮州工厂车间里的白色马桶，侧45度角..."
              className="w-full bg-white/[0.05] border border-white/10 rounded-2xl p-4 text-sm h-32 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 resize-none"
            />
          </section>
        )}

        {/* 场景与数量 */}
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <label className="text-[10px] font-black text-white/40 uppercase tracking-widest ml-1">空间场景</label>
            <select 
              value={config.environment}
              onChange={(e) => setConfig({...config, environment: e.target.value as EnvironmentType})}
              className="w-full bg-white/[0.05] border border-white/10 rounded-xl px-3 py-3 text-xs focus:outline-none"
            >
              {Object.values(EnvironmentType).map(env => <option key={env} value={env} className="bg-neutral-900">{env}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-black text-white/40 uppercase tracking-widest ml-1">批量数量</label>
            <select 
              value={config.batchCount}
              onChange={(e) => setConfig({...config, batchCount: Number(e.target.value)})}
              className="w-full bg-white/[0.05] border border-white/10 rounded-xl px-3 py-3 text-xs focus:outline-none"
            >
              {[1,2,3,4,5].map(n => <option key={n} value={n} className="bg-neutral-900">{n} 张结果</option>)}
            </select>
          </div>
        </div>

        <section className="space-y-2">
          <label className="text-[10px] font-black text-white/40 uppercase tracking-widest ml-1">艺术风格</label>
          <select 
            value={config.style}
            onChange={(e) => setConfig({...config, style: e.target.value as SceneStyle})}
            className="w-full bg-white/[0.05] border border-white/10 rounded-xl px-3 py-3 text-xs focus:outline-none"
          >
            {Object.values(SceneStyle).map(s => <option key={s} value={s} className="bg-neutral-900">{s}</option>)}
          </select>
        </section>

        <button 
          onClick={handleGenerate}
          disabled={isProcessing}
          className={`w-full py-5 rounded-3xl font-bold text-sm flex items-center justify-center gap-3 transition-all ${isProcessing ? 'bg-white/5 text-white/20' : 'bg-gradient-to-r from-indigo-600 to-purple-600 hover:scale-[1.02] shadow-xl shadow-indigo-600/20'}`}
        >
          {isProcessing ? <RefreshCw className="w-5 h-5 animate-spin" /> : <><Sparkles className="w-5 h-5" /> 生成多套商业大片</>}
        </button>
      </aside>

      {/* 主画布 */}
      <main className="flex-1 p-8 md:p-12 overflow-y-auto">
        {!result && !isProcessing && (
          <div className="h-full flex flex-col items-center justify-center opacity-20">
             <LayoutGrid className="w-16 h-16 mb-6" />
             <p className="tracking-[0.5em] text-xs uppercase font-bold">Lumina Studio Ready</p>
          </div>
        )}

        {isProcessing && (
          <div className="h-full flex flex-col items-center justify-center space-y-8">
             <div className="relative">
                <div className="w-24 h-24 border-2 border-indigo-500/20 rounded-full animate-ping" />
                <Sparkles className="w-8 h-8 text-indigo-500 absolute inset-0 m-auto animate-pulse" />
             </div>
             <p className="text-sm text-white/40 animate-pulse font-medium tracking-widest uppercase">正在并行创作多套视觉方案...</p>
          </div>
        )}

        {result && !isProcessing && (
          <div className="space-y-12">
            {/* 产品原图展示 */}
            <section className="flex items-center gap-8 bg-white/[0.02] p-6 rounded-[32px] border border-white/5">
              <div className="w-32 h-32 rounded-2xl overflow-hidden border border-white/10 flex-shrink-0">
                <img src={result.originalUrl} alt="Original" className="w-full h-full object-cover" />
              </div>
              <div>
                <div className="flex items-center gap-2 text-indigo-400 mb-1">
                  <CheckCircle2 className="w-4 h-4" />
                  <span className="text-xs font-bold uppercase tracking-wider">产品主体已就位</span>
                </div>
                <h2 className="text-xl font-bold">{config.mode === 'UPLOAD' ? '实拍上传' : 'AI 生成'}产品图</h2>
                <p className="text-xs text-white/30 mt-1">基于此主体已并行生成 {result.results.length} 套场景方案</p>
              </div>
            </section>

            {/* 结果网格 */}
            <section className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
              {result.results.map((url, index) => (
                <div key={index} className="group relative rounded-[40px] overflow-hidden bg-white/5 border border-white/10 aspect-square shadow-2xl transition-all hover:scale-[1.02]">
                  <img src={url} alt={`Result ${index}`} className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all duration-500 flex flex-col justify-end p-8">
                    <p className="text-xs font-bold text-white/60 mb-4 uppercase tracking-widest">方案 {index + 1} · {config.style}</p>
                    <div className="flex gap-2">
                      <button 
                        onClick={() => {
                          const link = document.createElement('a');
                          link.href = url;
                          link.download = `lumina-variant-${index+1}.png`;
                          link.click();
                        }}
                        className="flex-1 bg-white text-black py-3 rounded-2xl font-bold text-xs flex items-center justify-center gap-2"
                      >
                        <Download className="w-4 h-4" /> 下载 8K 样片
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </section>
          </div>
        )}

        {/* 聊天入口 */}
        <button 
          onClick={() => setShowChat(!showChat)}
          className={`fixed bottom-10 right-10 p-5 rounded-3xl shadow-2xl z-50 transition-all ${showChat ? 'bg-red-500 scale-90' : 'bg-indigo-600 hover:scale-110 hover:rotate-6'}`}
        >
          {showChat ? <X /> : <MessageSquare />}
        </button>

        {showChat && (
          <div className="fixed bottom-32 right-10 w-80 md:w-[400px] h-[550px] bg-[#121212] border border-white/10 rounded-[40px] shadow-2xl flex flex-col z-50 overflow-hidden animate-in slide-in-from-bottom-10">
             <header className="p-6 border-b border-white/5 bg-white/[0.02] flex items-center justify-between">
                <div className="flex items-center gap-3">
                   <div className="w-2.5 h-2.5 rounded-full bg-green-500" />
                   <span className="text-xs font-bold tracking-widest uppercase opacity-60">视觉顾问</span>
                </div>
                <button onClick={() => setShowChat(false)} className="opacity-20 hover:opacity-100"><X className="w-4 h-4" /></button>
             </header>
             <div className="flex-1 overflow-y-auto p-6 space-y-6">
                {chatMessages.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                     <div className={`max-w-[85%] px-5 py-3 rounded-2xl text-[13px] leading-relaxed ${msg.role === 'user' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white/5 border border-white/10 text-white/80'}`}>
                        {msg.text}
                     </div>
                  </div>
                ))}
                {isChatting && <div className="text-[10px] text-white/20 animate-pulse ml-2 font-bold">Thinking...</div>}
                <div ref={chatEndRef} />
             </div>
             <div className="p-6 border-t border-white/5">
                <div className="flex gap-3">
                   <input 
                     type="text" 
                     value={chatInput} 
                     onChange={e => setChatInput(e.target.value)}
                     onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
                     placeholder="询问后期修改建议..." 
                     className="flex-1 bg-black/40 border border-white/10 rounded-2xl px-5 py-3 text-sm focus:outline-none focus:ring-1 focus:ring-indigo-500 transition-all"
                   />
                   <button onClick={handleSendMessage} className="w-12 h-12 flex items-center justify-center bg-indigo-600 rounded-2xl hover:bg-indigo-500 transition-colors"><ChevronRight /></button>
                </div>
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

