    TASK: PRODUCT RE-STYLING. Keep the product from the image exactly the same.
    ${cleaningPrompt}
    LOCATION: Place it ${envPrompts[environment]}.
    STYLE: ${stylePrompts[style]}.
    USER DETAIL: ${customPrompt}
    QUALITY: Commercial photography, perfect perspective and shadows.
  `;

  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Image.includes(',') ? base64Image.split(',')[1] : base64Image,
    },
  };

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [imagePart, { text: finalPrompt }] },
    config: isPro ? {
      imageConfig: { aspectRatio: "1:1", imageSize: size }
    } : undefined
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("未返回图像数据");
};

import React, { useState, useRef, useEffect } from 'react';
import { 
