import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { SceneStyle, EnvironmentType, ImageSize } from "./types";

/**
 * 方案 B：生成原始产品图
 */
export const generateOriginalProduct = async (
  productDescription: string,
  size: ImageSize = ImageSize.SIZE_1K
): Promise<string> => {
  // Create instance right before call as per guidelines for Pro models/Key selection
  // Always use process.env.API_KEY directly as per guidelines
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

  const prompt = `
    TASK: Generate a professional commercial product photograph.
    SUBJECT: ${productDescription}.
    STYLE: Clean, high-end, studio lighting. 
    BACKGROUND: Pure white or neutral minimalist studio background. 
    QUALITY: 8k, sharp focus, commercial photography quality.
    COMPOSITION: Centered, full view of the product.
  `;

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: { parts: [{ text: prompt }] },
    config: {
      imageConfig: { aspectRatio: "1:1", imageSize: size }
    }
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  throw new Error("未能生成产品图");
};

export const replaceBackground = async (
  base64Image: string,
  environment: EnvironmentType,
  style: SceneStyle,
  customPrompt: string,
  isPro: boolean = false,
  size: ImageSize = ImageSize.SIZE_1K,
  addReference: boolean = false,
  cleanProduct: boolean = false
): Promise<string> => {
  // Always use process.env.API_KEY directly as per guidelines
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  const modelName = isPro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

  const envPrompts: Record<string, string> = {
    [EnvironmentType.BEDROOM]: "in a cozy, high-end bedroom setting, perhaps on a bedside table.",
    [EnvironmentType.DINING_ROOM]: "on a sophisticated dining table with elegant dinnerware.",
    [EnvironmentType.OUTDOOR_PICNIC]: "in a lush green outdoor garden on a picnic cloth.",
    [EnvironmentType.BATHROOM]: "in a clean, modern luxury bathroom on a marble vanity.",
    [EnvironmentType.LIVING_ROOM]: "in a designer living room on a coffee table.",
    [EnvironmentType.OFFICE]: "in a high-tech modern office on a polished desk.",
    [EnvironmentType.STUDIO]: "in a professional clean commercial photography studio.",
    [EnvironmentType.CAFE]: "in a trendy urban boutique cafe on a round wooden table."
  };

  const stylePrompts: Record<string, string> = {
    [SceneStyle.MODERN_LUXURY]: "High-end luxury aesthetics, marble textures, crisp look.",
    [SceneStyle.ZEN_MINIMALIST]: "Soft, peaceful Zen atmosphere, wood and stone elements.",
    [SceneStyle.C4D_GEOMETRIC]: "Professional 3D C4D render style, geometric shapes.",
    [SceneStyle.WINDOW_LIGHT]: "Soft natural morning sunlight through a window, airy feel.",
    [SceneStyle.WARM_BOKEH]: "Cinematic depth of field with golden hour bokeh.",
    [SceneStyle.BLACK_GOLD]: "Moody dark aesthetic, premium black slate, gold accents.",
    [SceneStyle.CHAOZHOU_RETRO]: "Nostalgic atmosphere with traditional Southern Chinese architecture elements."
  };

  const cleaningPrompt = cleanProduct 
    ? "PRODUCT RETOCHING: Digitally clean the product, remove dust and fingerprints."
    : "";

  const finalPrompt = `
    TASK: PRODUCT RE-STYLING. Keep the product from the image exactly the same.
    ${cleaningPrompt}
    LOCATION: Place it ${envPrompts[environment]}.
    STYLE: ${stylePrompts[style]}.
    USER DETAIL: ${customPrompt}
    QUALITY: Commercial photography, perfect perspective and shadows.
  `;

  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Image.includes(',') ? base64Image.split(',')[1] : base64Image,
    },
  };

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [imagePart, { text: finalPrompt }] },
    config: isPro ? {
      imageConfig: { aspectRatio: "1:1", imageSize: size }
    } : undefined
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("未返回图像数据");
};

import React, { useState, useRef, useEffect } from 'react';
import { 
  Upload, 
  Sparkles, 
  Download, 
  MessageSquare, 
  X, 
  ChevronRight,
  RefreshCw,
  LayoutGrid,
  Box,
  CheckCircle2,
  Key,
  ExternalLink,
  AlertCircle
} from 'lucide-react';
import { SceneStyle, EnvironmentType, ImageSize, GenerationConfig, ChatMessage, GenerationResult } from './types';
import { replaceBackground, generateOriginalProduct } from './geminiService';
import { GoogleGenAI, GenerateContentResponse } from '@google/genai';

// Removed manual declare global for window.aistudio to avoid conflict with existing AIStudio type provided by environment

const App: React.FC = () => {
  const [selectedFile, setSelectedFile] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);
  const [hasKey, setHasKey] = useState<boolean | null>(null);
  const [config, setConfig] = useState<GenerationConfig>({
    environment: EnvironmentType.DINING_ROOM,
    style: SceneStyle.WINDOW_LIGHT,
    customPrompt: '',
    isPro: true,
    size: ImageSize.SIZE_1K,
    addReference: true,
    cleanProduct: false,
    mode: 'UPLOAD',
    productPrompt: '一套极简主义风格的白色骨瓷茶具',
    batchCount: 3
  });

  const [showChat, setShowChat] = useState(false);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isChatting, setIsChatting] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const checkKey = async () => {
      // Use ts-ignore for platform-injected globals to avoid build-time conflicts
      // @ts-ignore
      if (window.aistudio) {
        // @ts-ignore
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasKey(selected);
      } else {
        // Fallback if not in environment with aistudio global
        setHasKey(true);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    // @ts-ignore
    if (window.aistudio) {
      // @ts-ignore
      await window.aistudio.openSelectKey();
      setHasKey(true); // Assume success per instructions
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setSelectedFile(event.target?.result as string);
        setResult(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    setIsProcessing(true);
    try {
      let baseImage = selectedFile;

      if (config.mode === 'AI_GEN') {
        baseImage = await generateOriginalProduct(config.productPrompt, config.size);
        setSelectedFile(baseImage);
      }

      if (!baseImage) {
        alert("请先上传图片或描述产品");
        setIsProcessing(false);
        return;
      }

      const tasks = Array.from({ length: config.batchCount }).map(() => 
        replaceBackground(
          baseImage!,
          config.environment,
          config.style,
          config.customPrompt,
          config.isPro,
          config.size,
          config.addReference,
          config.cleanProduct
        )
      );

      const resultUrls = await Promise.all(tasks);

      setResult({
        originalUrl: baseImage,
        results: resultUrls,
        id: Date.now().toString()
      });
    } catch (error: any) {
      console.error("生成失败:", error);
      const errorMsg = error.message || "";
      if (errorMsg.includes("403") || errorMsg.includes("permission") || errorMsg.includes("not found")) {
        setHasKey(false);
        alert("权限验证失败，请重新选择有效的付费 API Key。");
      } else {
        alert(`生成失败: ${errorMsg}`);
      }
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSendMessage = async () => {
    if (!chatInput.trim()) return;
    const userMsg: ChatMessage = { role: 'user', text: chatInput };
    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatting(true);
    try {
      // Always use process.env.API_KEY directly as per guidelines
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const chat = ai.chats.create({
        model: 'gemini-3-pro-preview',
        config: { systemInstruction: "你是一位视觉工作室专家。请用中文回答。" }
      });
