import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { SceneStyle, EnvironmentType, ImageSize } from "./types";

/**
 * 生成原始产品图 (方案 B)
 */
export const generateOriginalProduct = async (
  productDescription: string,
  size: ImageSize = ImageSize.SIZE_1K,
  usePro: boolean = false
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  const modelName = usePro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

  const prompt = `
    TASK: Generate a high-end, commercial-grade product photograph.
    SUBJECT: ${productDescription}.
    SETTING: Placed on a pure white, infinite studio background. 
    LIGHTING: Softbox studio lighting, perfectly balanced, no harsh shadows.
    CAMERA: 85mm lens, f/8, sharp focus across the entire product.
    QUALITY: Ultra-high definition, clean edges, professional retouching.
  `;

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [{ text: prompt }] },
    config: usePro ? {
      imageConfig: { aspectRatio: "1:1", imageSize: size }
    } : undefined
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  throw new Error("未能生成产品图，请检查 API 状态。");
};

/**
 * 替换背景 - 深度增强版
 */
export const replaceBackground = async (
  base64Image: string,
  environment: EnvironmentType,
  style: SceneStyle,
  customPrompt: string,
  isPro: boolean = false,
  size: ImageSize = ImageSize.SIZE_1K,
  addReference: boolean = true,
  cleanProduct: boolean = false
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  const modelName = isPro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

  const envPrompts: Record<string, string> = {
    [EnvironmentType.BEDROOM]: "in a luxury hotel suite bedroom, soft silk linens, warm ambient bedside lighting, expensive interior design.",
    [EnvironmentType.DINING_ROOM]: "on a solid walnut dining table, set with minimalist fine-dining ceramics, soft evening sunlight through high windows.",
    [EnvironmentType.OUTDOOR_PICNIC]: "in a sun-drenched meadow, lush green grass, soft morning dew, beautiful natural outdoor lighting.",
    [EnvironmentType.BATHROOM]: "on a white Carrara marble vanity in a modern high-end bathroom, soft diffused lighting, spa-like atmosphere.",
    [EnvironmentType.LIVING_ROOM]: "on a contemporary designer coffee table, architectural living space, morning soft light, high-end furniture.",
    [EnvironmentType.OFFICE]: "in a sleek minimalist executive office, glass desk, urban skyline background blurred in distance.",
    [EnvironmentType.STUDIO]: "in a professional product photography studio, clean cyclorama background, perfect key lighting.",
    [EnvironmentType.CAFE]: "on a small round wooden table in a boutique urban cafe, warm pendant lighting, blurred background of a coffee shop."
  };

  const stylePrompts: Record<string, string> = {
    [SceneStyle.MODERN_LUXURY]: "High-end luxury aesthetic, glossy surfaces, deep contrast, professional retouching, sharp focus.",
    [SceneStyle.ZEN_MINIMALIST]: "Zen wabi-sabi philosophy, natural materials like wood and stone, plenty of negative space, soft neutral colors.",
    [SceneStyle.C4D_GEOMETRIC]: "Professional 3D C4D octane render, geometric pedestals, abstract light play, clean futuristic shapes.",
    [SceneStyle.WINDOW_LIGHT]: "Ethereal natural window light with 'god rays', cinematic dust particles, airy and bright, soft shadows.",
    [SceneStyle.WARM_BOKEH]: "Warm candle-lit atmosphere, beautiful circular bokeh in the background, intimate and cozy vibes.",
    [SceneStyle.BLACK_GOLD]: "Luxury black-on-black aesthetic with gold metallic accents, high-key drama, moody lighting.",
    [SceneStyle.CHAOZHOU_RETRO]: "Nostalgic Southern Chinese retro style, traditional tile textures, tea culture elements, warm vintage film grain."
  };

  // 关键增强：产品清洁与参照物逻辑
  const cleaningMod = cleanProduct ? "DIGITAL RETOUCHING: Remove all fingerprints, dust, and minor imperfections from the product surface to make it look brand new and polished." : "";
  const referenceMod = addReference ? "CONTEXTUAL ELEMENTS: Add tasteful, relevant small items (like a flower vase, a magazine, or coasters) to the scene to make it look lived-in and realistic." : "MINIMALIST: Keep the product as the sole focus without any distracting side objects.";

  const finalPrompt = `
    TASK: PRODUCT BACKGROUND REPLACEMENT. 
    CONSTRAINT: The product from the source image must remain 100% structurally identical.
    ${cleaningMod}
    SCENE: Place the product ${envPrompts[environment]}.
    ARTISTIC DIRECTION: ${stylePrompts[style]}.
    ${referenceMod}
    ADDITIONAL DETAILS: ${customPrompt}
    TECHNICAL QUALITY: 8k resolution, realistic shadows that ground the product, global illumination, ray-traced reflections, professional commercial look.
  `;

  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Image.includes(',') ? base64Image.split(',')[1] : base64Image,
    },
  };

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [imagePart, { text: finalPrompt }] },
    config: isPro ? {
      imageConfig: { aspectRatio: "1:1", imageSize: size }
    } : undefined
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("图像生成中断，可能触发了安全策略或 API 限制。");
};

