          </div>
        </div>

        <section className="space-y-2">
          <label className="text-[10px] font-black text-white/40 uppercase tracking-widest ml-1">光影风格</label>
          <select 
            value={config.style}
            onChange={(e) => setConfig({...config, style: e.target.value as SceneStyle})}
            className="w-full bg-white/[0.05] border border-white/10 rounded-xl px-3 py-3 text-xs focus:outline-none appearance-none cursor-pointer"
