            {Object.values(SceneStyle).map(s => <option key={s} value={s} className="bg-neutral-900">{s}</option>)}
          </select>
        </section>

        <button 
          onClick={handleGenerate}
          disabled={isProcessing}
          className={`w-full py-5 rounded-3xl font-bold text-sm flex items-center justify-center gap-3 transition-all ${isProcessing ? 'bg-white/5 text-white/20' : 'bg-gradient-to-r from-indigo-600 to-purple-600 hover:shadow-indigo-600/30 hover:scale-[1.02] shadow-xl active:scale-[0.98]'}`}
        >
          {isProcessing ? <RefreshCw className="w-5 h-5 animate-spin" /> : <><Zap className="w-4 h-4" /> 物理级背景替换</>}
        </button>
      </aside>

      <main className="flex-1 p-8 md:p-12 overflow-y-auto">
        {!result && !isProcessing && (
          <div className="h-full flex flex-col items-center justify-center opacity-20">
             <LayoutGrid className="w-16 h-16 mb-6" />
             <p className="tracking-[0.5em] text-xs uppercase font-bold text-center">Lumina Engine Ready</p>
          </div>
        )}

        {isProcessing && (
          <div className="h-full flex flex-col items-center justify-center space-y-8">
             <div className="relative">
                <div className="w-24 h-24 border-2 border-indigo-500/20 rounded-full animate-ping" />
                <Sparkles className="w-8 h-8 text-indigo-500 absolute inset-0 m-auto animate-pulse" />
             </div>
             <div className="text-center space-y-2">
                <p className="text-sm text-white/60 font-medium tracking-widest uppercase">正在计算环境光屏蔽 (Ambient Occlusion)...</p>
                <p className="text-[10px] text-white/20 uppercase tracking-tighter">正在匹配相机透视并注入全局光照数据</p>
             </div>
          </div>
        )}

        {result && !isProcessing && (
          <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <section className="flex items-center gap-8 bg-white/[0.02] p-6 rounded-[32px] border border-white/5">
              <div className="w-32 h-32 rounded-2xl overflow-hidden border border-white/10 flex-shrink-0 bg-black/40">
                <img src={result.originalUrl} alt="Original" className="w-full h-full object-contain" />
              </div>
              <div>
                <div className="flex items-center gap-2 text-indigo-400 mb-1">
                  <CheckCircle2 className="w-4 h-4" />
                  <span className="text-xs font-bold uppercase tracking-wider">物理对齐完成</span>
                </div>
                <h2 className="text-xl font-bold">{config.mode === 'UPLOAD' ? '上传' : 'AI'} 产品</h2>
                <p className="text-xs text-white/30 mt-1">已成功输出 {result.results.length} 套增强型样片</p>
              </div>
            </section>

            <section className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6 pb-20">
              {result.results.map((url, index) => (
                <div key={index} className="group relative rounded-[40px] overflow-hidden bg-white/5 border border-white/10 aspect-square shadow-2xl transition-all hover:scale-[1.02] hover:border-indigo-500/30">
                  <img src={url} alt={`Result ${index}`} className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all duration-500 flex flex-col justify-end p-8">
                    <p className="text-xs font-bold text-white/60 mb-4 uppercase tracking-widest">方案 {index + 1} · {config.style}</p>
                    <button 
                      onClick={() => {
                        const link = document.createElement('a');
                        link.href = url;
                        link.download = `lumina-pro-${index+1}.png`;
                        link.click();
                      }}
                      className="w-full bg-white text-black py-3 rounded-2xl font-bold text-xs flex items-center justify-center gap-2 hover:bg-indigo-50 active:scale-95 transition-all"
                    >
                      <Download className="w-4 h-4" /> 下载 8K 无损样片
                    </button>
                  </div>
                </div>
              ))}
            </section>
          </div>
        )}

        <button 
          onClick={() => setShowChat(!showChat)}
          className={`fixed bottom-10 right-10 p-5 rounded-3xl shadow-2xl z-50 transition-all ${showChat ? 'bg-red-500 scale-90' : 'bg-indigo-600 hover:scale-110 hover:shadow-indigo-600/50'}`}
        >
          {showChat ? <X /> : <MessageSquare />}
        </button>

        {showChat && (
          <div className="fixed bottom-32 right-10 w-80 md:w-[400px] h-[550px] bg-[#121212] border border-white/10 rounded-[40px] shadow-2xl flex flex-col z-50 overflow-hidden animate-in slide-in-from-bottom-10">
             <header className="p-6 border-b border-white/5 bg-white/[0.02] flex items-center justify-between">
                <div className="flex items-center gap-3">
                   <div className="w-2.5 h-2.5 rounded-full bg-indigo-500 animate-pulse" />
                   <span className="text-xs font-bold tracking-widest uppercase opacity-60">摄影顾问</span>
                </div>
                <button onClick={() => setShowChat(false)} className="opacity-20 hover:opacity-100 transition-opacity"><X className="w-4 h-4" /></button>
             </header>
             <div className="flex-1 overflow-y-auto p-6 space-y-6">
                {chatMessages.length === 0 && (
                  <div className="text-center py-10 opacity-20 space-y-2">
                    <MessageSquare className="w-8 h-8 mx-auto" />
                    <p className="text-[10px] uppercase font-bold tracking-widest">等待您的咨询...</p>
                  </div>
                )}
                {chatMessages.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                     <div className={`max-w-[85%] px-5 py-3 rounded-2xl text-[13px] leading-relaxed ${msg.role === 'user' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white/5 border border-white/10 text-white/80'}`}>
                        {msg.text}
                     </div>
                  </div>
                ))}
                {isChatting && <div className="text-[10px] text-white/20 animate-pulse ml-2 font-bold tracking-widest">正在分析画面光影...</div>}
                <div ref={chatEndRef} />
             </div>
             <div className="p-6 border-t border-white/5 bg-black/40">
                <div className="flex gap-3">
                   <input 
                     type="text" 
                     value={chatInput} 
                     onChange={e => setChatInput(e.target.value)}
                     onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
                     placeholder="询问修正建议，如'光效不匹配'..." 
                     className="flex-1 bg-black/40 border border-white/10 rounded-2xl px-5 py-3 text-sm focus:outline-none focus:ring-1 focus:ring-indigo-500 transition-all"
                   />
                   <button onClick={handleSendMessage} className="w-12 h-12 flex items-center justify-center bg-indigo-600 rounded-2xl hover:bg-indigo-500 transition-colors shadow-lg active:scale-95"><ChevronRight /></button>
                </div>
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { SceneStyle, EnvironmentType, ImageSize } from "./types";

/**
 * 生成原始产品图 (方案 B)
 */
export const generateOriginalProduct = async (
  productDescription: string,
  size: ImageSize = ImageSize.SIZE_1K,
  usePro: boolean = false
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  const modelName = usePro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

  const prompt = `
    [COMMERCIAL STUDIO PROTOCOL]
    - SUBJECT: ${productDescription}.
    - BACKDROP: Pure #FFFFFF infinite cyclorama.
    - LIGHTING: 3-point butterfly lighting, ultra-soft shadows, professional CRI 95+ light sources.
    - OPTICS: 100mm Prime Macro lens, f/11, razor-sharp focus on subject textures.
    - FINISH: 8k UHD resolution, raw photography style, no artistic filters.
  `;

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [{ text: prompt }] },
    config: usePro ? {
      imageConfig: { aspectRatio: "1:1", imageSize: size }
    } : undefined
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  throw new Error("生成失败");
};

/**
 * 替换背景 - 物理渲染回溯增强版
 */
export const replaceBackground = async (
  base64Image: string,
  environment: EnvironmentType,
  style: SceneStyle,
  customPrompt: string,
  isPro: boolean = false,
  size: ImageSize = ImageSize.SIZE_1K,
  addReference: boolean = true,
  cleanProduct: boolean = false
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  const modelName = isPro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

  const envPrompts: Record<string, string> = {
    [EnvironmentType.BEDROOM]: "inside a high-end luxury bedroom suite, focused on a boutique nightstand, soft cinematic morning light.",
    [EnvironmentType.DINING_ROOM]: "on an elegant minimalist dining table, fine wood grain textures, natural window light from the side.",
    [EnvironmentType.OUTDOOR_PICNIC]: "on a rustic linen cloth in a sunny meadow, dappled sunlight, lush natural environment.",
    [EnvironmentType.BATHROOM]: "on a white marble vanity in a contemporary spa bathroom, soft diffused overhead lighting.",
    [EnvironmentType.LIVING_ROOM]: "on a designer modern coffee table, architectural interior, high-end loft atmosphere.",
    [EnvironmentType.OFFICE]: "on a clean professional executive desk, modern tech-office aesthetic, soft overhead studio light.",
    [EnvironmentType.STUDIO]: "in a professional product studio with controlled softbox lighting and clean background gradients.",
    [EnvironmentType.CAFE]: "on a round marble table at an upscale boutique cafe, blurred urban street background, warm interior lighting."
  };

  const stylePrompts: Record<string, string> = {
    [SceneStyle.MODERN_LUXURY]: "Premium luxury look, high contrast, glossy finishes, rich metallic reflections, crisp details.",
    [SceneStyle.ZEN_MINIMALIST]: "Soft neutral tones, organic textures, natural materials, clean compositions, peaceful lighting.",
    [SceneStyle.C4D_GEOMETRIC]: "Professional Octane Render style, geometric pedestals, abstract sculptural lighting, digital art aesthetic.",
    [SceneStyle.WINDOW_LIGHT]: "Strong directional window light casting soft cinematic shadows, volumetric dust motes, airy vibe.",
    [SceneStyle.WARM_BOKEH]: "Deep depth of field, f/1.4 lens effect, warm tungsten glow, beautiful circular background bokeh.",
    [SceneStyle.BLACK_GOLD]: "Dramatic low-key lighting, deep black void background, golden accent lighting, high-end mystery.",
    [SceneStyle.CHAOZHOU_RETRO]: "Nostalgic 1990s vintage film aesthetic, soft warm color grading, traditional tile textures, soft top light."
  };

  // 关键增强：材质保留逻辑，防止塑料感
  const retouchingMod = cleanProduct 
    ? "RETOUCHING: Perform professional high-end retouching. Remove dust and scratches but PRESERVE all original material textures and surface details. Do not over-smooth." 
    : "RAW: Keep all original surface characteristics.";

  const referenceMod = addReference 
    ? "STYLING: Integrate the product with subtle high-quality props (e.g., a single leaf, a glass of water, or a book) to establish scale and realism." 
    : "MINIMALIST: Zero props, focus solely on the product integration.";

  const finalPrompt = `
    [ULTRA-REALISTIC INTEGRATION PROTOCOL]
    - RAY-TRACING: Calculate real-time global illumination and environment color bleeding onto the product surface.
    - SHADOWS: Generate high-fidelity contact shadows with accurate soft falloff (Ambient Occlusion) at the base.
    - LENS: 85mm Prime Photography lens, f/8 aperture, physically accurate perspective matching.
    - LIGHT-WRAPPING: Background light must subtly bleed over the edges of the product to ensure seamless blending.
    - MATERIALITY: Enhance subsurface scattering for ceramics/liquids and realistic specular reflections.

    SCENE: ${envPrompts[environment]}.
    ARTISTIC STYLE: ${stylePrompts[style]}.
    ${retouchingMod}
    ${referenceMod}
    ADDITIONAL INFO: ${customPrompt}

    COMPULSORY: The product must look like it was physically present in the location when the photo was taken. No 'sticker' effect.
  `;

  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Image.includes(',') ? base64Image.split(',')[1] : base64Image,
    },
  };

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [imagePart, { text: finalPrompt }] },
    config: isPro ? {
      imageConfig: { aspectRatio: "1:1", imageSize: size }
    } : undefined
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("生成失败，请重试");
};

import React, { useState, useRef, useEffect } from 'react';
import { 
  Upload, 
  Sparkles, 
  Download, 
  MessageSquare, 
  X, 
  ChevronRight,
  RefreshCw,
  LayoutGrid,
  Box,
  CheckCircle2,
  Key,
  Check,
  Zap,
  Layers
} from 'lucide-react';
import { SceneStyle, EnvironmentType, ImageSize, GenerationConfig, ChatMessage, GenerationResult } from './types';
import { replaceBackground, generateOriginalProduct } from './geminiService';
import { GoogleGenAI, GenerateContentResponse } from '@google/genai';

const App: React.FC = () => {
  const [selectedFile, setSelectedFile] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);

  const [config, setConfig] = useState<GenerationConfig>({
    environment: EnvironmentType.DINING_ROOM,
    style: SceneStyle.WINDOW_LIGHT,
    customPrompt: '',
    isPro: false,
    size: ImageSize.SIZE_1K,
    addReference: true,
    cleanProduct: true,
    mode: 'UPLOAD',
    productPrompt: '一套极简主义风格的白色骨瓷茶具',
    batchCount: 2
  });

  const [showChat, setShowChat] = useState(false);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isChatting, setIsChatting] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const handleSelectKey = async () => {
    // @ts-ignore
    if (window.aistudio?.openSelectKey) {
      // @ts-ignore
      await window.aistudio.openSelectKey();
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setSelectedFile(event.target?.result as string);
        setResult(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    setIsProcessing(true);
    try {
      let baseImage = selectedFile;

      if (config.mode === 'AI_GEN') {
        baseImage = await generateOriginalProduct(config.productPrompt, config.size, config.isPro);
        setSelectedFile(baseImage);
      }

      if (!baseImage) {
        alert("请先上传图片或描述产品");
        setIsProcessing(false);
        return;
      }

      const tasks = Array.from({ length: config.batchCount }).map(() => 
        replaceBackground(
          baseImage!,
          config.environment,
          config.style,
          config.customPrompt,
          config.isPro,
          config.size,
          config.addReference,
          config.cleanProduct
        )
      );

      const resultUrls = await Promise.all(tasks);

      setResult({
        originalUrl: baseImage,
        results: resultUrls,
        id: Date.now().toString()
      });
    } catch (error: any) {
      console.error("生成失败:", error);
      const errorMsg = error.message || "";
      if (errorMsg.includes("403") || errorMsg.includes("permission")) {
        if (confirm("提示：当前画质受限。建议选择付费项目 API Key 以解锁 4K 高保真渲染。是否切换？")) {
          handleSelectKey();
        }
      } else {
        alert(`生成失败: ${errorMsg}`);
      }
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSendMessage = async () => {
    if (!chatInput.trim()) return;
    const userMsg: ChatMessage = { role: 'user', text: chatInput };
    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatting(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: { systemInstruction: "你是一位资深商业摄影后期总监。专注于光影包裹（Light Wrapping）、次表面散射和物理材质的表现。请用中文提供专业建议。" }
      });
      const response: GenerateContentResponse = await chat.sendMessage({ message: chatInput });
      const modelMsg: ChatMessage = { role: 'model', text: response.text || '抱歉，暂时无法回答。' };
      setChatMessages(prev => [...prev, modelMsg]);
    } catch (error) {
      console.error("对话错误:", error);
    } finally {
      setIsChatting(false);
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#080808] text-white selection:bg-indigo-500/30 font-sans">
      <aside className="w-full md:w-[400px] border-r border-white/5 bg-[#0c0c0c] p-8 flex flex-col gap-6 overflow-y-auto">
        <header className="flex items-center gap-4 mb-2">
          <div className="p-2.5 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-2xl shadow-lg">
            <Sparkles className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="font-bold text-xl tracking-tight">崇正视觉</h1>
            <p className="text-[10px] text-white/30 uppercase tracking-[0.2em]">Ultra-Fidelity Studio</p>
          </div>
        </header>

        <section className="bg-white/5 p-1 rounded-2xl flex gap-1">
          <button 
            onClick={() => setConfig({...config, mode: 'UPLOAD'})}
            className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all ${config.mode === 'UPLOAD' ? 'bg-indigo-600 text-white shadow-lg' : 'text-white/40 hover:text-white/60'}`}
          >实拍上传</button>
          <button 
            onClick={() => setConfig({...config, mode: 'AI_GEN'})}
            className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all ${config.mode === 'AI_GEN' ? 'bg-indigo-600 text-white shadow-lg' : 'text-white/40 hover:text-white/60'}`}
          >AI 创作</button>
        </section>

        {/* 细节增强控制区 (深度增强) */}
        <div className="space-y-2">
          <label className="text-[10px] font-black text-white/40 uppercase tracking-widest ml-1">高保真渲染选项</label>
          <div className="grid grid-cols-2 gap-2">
             <button 
               onClick={() => setConfig({...config, cleanProduct: !config.cleanProduct})}
               className={`flex items-center justify-between px-4 py-3 rounded-2xl text-[11px] font-bold border transition-all ${config.cleanProduct ? 'bg-indigo-600/10 border-indigo-500/50 text-indigo-400' : 'bg-white/[0.02] border-white/5 text-white/30'}`}
             >
               专业修图
               {config.cleanProduct ? <Check className="w-3 h-3" /> : <Layers className="w-3 h-3 opacity-20" />}
             </button>
             <button 
               onClick={() => setConfig({...config, addReference: !config.addReference})}
               className={`flex items-center justify-between px-4 py-3 rounded-2xl text-[11px] font-bold border transition-all ${config.addReference ? 'bg-indigo-600/10 border-indigo-500/50 text-indigo-400' : 'bg-white/[0.02] border-white/5 text-white/30'}`}
             >
               场景写实
               {config.addReference ? <Check className="w-3 h-3" /> : <Box className="w-3 h-3 opacity-20" />}
             </button>
          </div>
        </div>

        <section className="bg-indigo-600/10 border border-indigo-500/20 p-4 rounded-2xl space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Zap className={`w-4 h-4 ${config.isPro ? 'text-indigo-400' : 'text-white/20'}`} />
              <span className="text-xs font-bold">Pro 级物理引擎</span>
            </div>
            <button 
              onClick={() => {
                if (!config.isPro) {
                  if (confirm("Pro 模式将强制开启光线追踪渲染，获得极致阴影和光影包裹效果。确认？")) {
                    setConfig({...config, isPro: true});
                  }
                } else {
                  setConfig({...config, isPro: false});
                }
              }}
              className={`w-10 h-5 rounded-full relative transition-all ${config.isPro ? 'bg-indigo-600' : 'bg-white/10'}`}
            >
              <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${config.isPro ? 'left-6' : 'left-1'}`} />
            </button>
          </div>
          <p className="text-[10px] text-white/40 leading-relaxed italic">当前已注入 Light-Wrapping 算法以提升融合度。</p>
        </section>

        {config.mode === 'UPLOAD' ? (
          <section className="space-y-4">
            <div className="flex items-center gap-2">
               <Upload className="w-3 h-3 text-indigo-400" />
               <label className="text-[10px] font-black text-white/40 uppercase tracking-widest">产品原图</label>
            </div>
            <div className={`relative group cursor-pointer border-2 border-dashed ${selectedFile ? 'border-indigo-500/50 bg-indigo-500/5' : 'border-white/5 bg-white/[0.02]'} rounded-3xl aspect-square flex items-center justify-center overflow-hidden transition-all`}>
              {selectedFile ? (
                <img src={selectedFile} alt="Preview" className="w-full h-full object-contain p-4 transition-transform group-hover:scale-105" />
              ) : (
                <div className="text-center p-6"><Upload className="w-8 h-8 text-white/20 mx-auto mb-2" /></div>
              )}
              <input type="file" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" />
            </div>
          </section>
        ) : (
          <section className="space-y-4">
            <div className="flex items-center gap-2">
               <Box className="w-3 h-3 text-indigo-400" />
               <label className="text-[10px] font-black text-white/40 uppercase tracking-widest">产品描述</label>
            </div>
            <textarea 
              value={config.productPrompt}
              onChange={(e) => setConfig({...config, productPrompt: e.target.value})}
              placeholder="例如：哑光釉面陶瓷杯..."
              className="w-full bg-white/[0.05] border border-white/10 rounded-2xl p-4 text-sm h-32 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 resize-none transition-all"
            />
          </section>
        )}

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <label className="text-[10px] font-black text-white/40 uppercase tracking-widest ml-1">空间场景</label>
            <select 
              value={config.environment}
              onChange={(e) => setConfig({...config, environment: e.target.value as EnvironmentType})}
              className="w-full bg-white/[0.05] border border-white/10 rounded-xl px-3 py-3 text-xs focus:outline-none appearance-none"
            >
              {Object.values(EnvironmentType).map(env => <option key={env} value={env} className="bg-neutral-900">{env}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-black text-white/40 uppercase tracking-widest ml-1">批量方案</label>
            <select 
              value={config.batchCount}
              onChange={(e) => setConfig({...config, batchCount: Number(e.target.value)})}
              className="w-full bg-white/[0.05] border border-white/10 rounded-xl px-3 py-3 text-xs focus:outline-none appearance-none"
            >
              {[1,2,3,4,5].map(n => <option key={n} value={n} className="bg-neutral-900">{n} 个方案</option>)}
            </select>
          </div>
        </div>

        <section className="space-y-2">
          <label className="text-[10px] font-black text-white/40 uppercase tracking-widest ml-1">视觉调性</label>
          <select 
            value={config.style}
            onChange={(e) => setConfig({...config, style: e.target.value as SceneStyle})}
            className="w-full bg-white/[0.05] border border-white/10 rounded-xl px-3 py-3 text-xs focus:outline-none appearance-none"
          >
            {Object.values(SceneStyle).map(s => <option key={s} value={s} className="bg-neutral-900">{s}</option>)}
          </select>
        </section>

        <button 
          onClick={handleGenerate}
          disabled={isProcessing}
          className={`w-full py-5 rounded-3xl font-bold text-sm flex items-center justify-center gap-3 transition-all ${isProcessing ? 'bg-white/5 text-white/20' : 'bg-gradient-to-r from-indigo-600 to-purple-600 hover:shadow-indigo-600/30 hover:scale-[1.02] shadow-xl active:scale-[0.98]'}`}
        >
          {isProcessing ? <RefreshCw className="w-5 h-5 animate-spin" /> : <><Sparkles className="w-4 h-4" /> 物理级背景渲染</>}
        </button>
      </aside>

      <main className="flex-1 p-8 md:p-12 overflow-y-auto">
        {!result && !isProcessing && (
          <div className="h-full flex flex-col items-center justify-center opacity-20">
             <LayoutGrid className="w-16 h-16 mb-6" />
             <p className="tracking-[0.5em] text-xs uppercase font-bold text-center">Fidelity Engine Ready</p>
          </div>
        )}

        {isProcessing && (
          <div className="h-full flex flex-col items-center justify-center space-y-8 animate-in fade-in">
             <div className="relative">
                <div className="w-24 h-24 border-2 border-indigo-500/20 rounded-full animate-ping" />
                <Sparkles className="w-8 h-8 text-indigo-500 absolute inset-0 m-auto animate-pulse" />
             </div>
             <div className="text-center space-y-3">
                <p className="text-sm text-white/70 font-bold tracking-widest uppercase">正在执行次表面散射与光影包裹算法...</p>
                <div className="flex items-center justify-center gap-2">
                  <div className="w-1 h-1 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.3s]" />
                  <div className="w-1 h-1 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.15s]" />
                  <div className="w-1 h-1 bg-indigo-500 rounded-full animate-bounce" />
                </div>
                <p className="text-[10px] text-white/20 uppercase tracking-tighter">匹配全局光照 (GI) 与物理透视</p>
             </div>
          </div>
        )}

        {result && !isProcessing && (
          <div className="space-y-12 animate-in fade-in duration-1000">
            <section className="flex items-center gap-8 bg-white/[0.02] p-6 rounded-[32px] border border-white/5">
              <div className="w-32 h-32 rounded-2xl overflow-hidden border border-white/10 flex-shrink-0 bg-black/40 shadow-inner">
                <img src={result.originalUrl} alt="Original" className="w-full h-full object-contain" />
              </div>
              <div>
                <div className="flex items-center gap-2 text-indigo-400 mb-1">
                  <CheckCircle2 className="w-4 h-4" />
                  <span className="text-xs font-bold uppercase tracking-wider">高保真渲染完成</span>
                </div>
                <h2 className="text-xl font-bold">产品主体已就绪</h2>
                <p className="text-xs text-white/30 mt-1">基于物理光效生成的 {result.results.length} 套方案</p>
              </div>
            </section>

            <section className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-8 pb-20">
              {result.results.map((url, index) => (
                <div key={index} className="group relative rounded-[48px] overflow-hidden bg-white/5 border border-white/10 aspect-square shadow-2xl transition-all hover:scale-[1.02] hover:border-indigo-500/30">
                  <img src={url} alt={`Result ${index}`} className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all duration-500 flex flex-col justify-end p-10">
                    <p className="text-xs font-bold text-white/60 mb-4 uppercase tracking-widest">方案 {index + 1} · {config.style}</p>
                    <button 
                      onClick={() => {
                        const link = document.createElement('a');
                        link.href = url;
                        link.download = `lumina-fidelity-${index+1}.png`;
                        link.click();
                      }}
                      className="w-full bg-white text-black py-4 rounded-2xl font-bold text-xs flex items-center justify-center gap-2 hover:bg-indigo-50 active:scale-95 transition-all shadow-xl"
                    >
                      <Download className="w-4 h-4" /> 下载 8K 原片
                    </button>
                  </div>
                </div>
              ))}
            </section>
          </div>
        )}

        {/* 聊天入口 */}
        <button 
          onClick={() => setShowChat(!showChat)}
          className={`fixed bottom-10 right-10 p-5 rounded-3xl shadow-2xl z-50 transition-all ${showChat ? 'bg-red-500 rotate-90 scale-90' : 'bg-indigo-600 hover:scale-110 hover:shadow-indigo-600/50'}`}
        >
          {showChat ? <X /> : <MessageSquare />}
        </button>

        {showChat && (
          <div className="fixed bottom-32 right-10 w-80 md:w-[400px] h-[550px] bg-[#121212] border border-white/10 rounded-[40px] shadow-2xl flex flex-col z-50 overflow-hidden animate-in slide-in-from-bottom-10">
             <header className="p-6 border-b border-white/5 bg-white/[0.02] flex items-center justify-between">
                <div className="flex items-center gap-3">
                   <div className="w-2.5 h-2.5 rounded-full bg-indigo-500 animate-pulse" />
                   <span className="text-xs font-bold tracking-widest uppercase opacity-60">后期总监</span>
                </div>
                <button onClick={() => setShowChat(false)} className="opacity-20 hover:opacity-100 transition-opacity"><X className="w-4 h-4" /></button>
             </header>
             <div className="flex-1 overflow-y-auto p-6 space-y-6">
                {chatMessages.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                     <div className={`max-w-[85%] px-5 py-3 rounded-2xl text-[13px] leading-relaxed ${msg.role === 'user' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white/5 border border-white/10 text-white/80'}`}>
                        {msg.text}
                     </div>
                  </div>
                ))}
                {isChatting && <div className="text-[10px] text-white/20 animate-pulse ml-2 font-bold tracking-widest uppercase">Analyzing Material Physics...</div>}
                <div ref={chatEndRef} />
             </div>
             <div className="p-6 border-t border-white/5 bg-black/40">
                <div className="flex gap-3">
                   <input 
                     type="text" 
                     value={chatInput} 
                     onChange={e => setChatInput(e.target.value)}
                     onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
                     placeholder="关于光影融合的建议..." 
                     className="flex-1 bg-black/40 border border-white/10 rounded-2xl px-5 py-3 text-sm focus:outline-none focus:ring-1 focus:ring-indigo-500 transition-all"
                   />
                   <button onClick={handleSendMessage} className="w-12 h-12 flex items-center justify-center bg-indigo-600 rounded-2xl hover:bg-indigo-500 transition-colors shadow-lg active:scale-95"><ChevronRight /></button>
                </div>
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

