  LIVING_ROOM = '客厅',
  OFFICE = '办公室',
  STUDIO = '专业摄影棚',
  CAFE = '精品咖啡馆'
}

export enum SceneStyle {
  MODERN_LUXURY = '现代奢华',
  ZEN_MINIMALIST = '禅意极简',
  C4D_GEOMETRIC = 'C4D 3D渲染',
  WINDOW_LIGHT = '自然窗光',
  WARM_BOKEH = '温馨灯影',
  BLACK_GOLD = '黑金质感',
  CHAOZHOU_RETRO = '潮汕复古'
}

export enum ImageSize {
  SIZE_1K = '1K',
  SIZE_2K = '2K',
  SIZE_4K = '4K'
}

export interface GenerationConfig {
  environment: EnvironmentType;
  style: SceneStyle;
  customPrompt: string;
  isPro: boolean;
  size: ImageSize;
  addReference: boolean;
  cleanProduct: boolean;
  mode: 'UPLOAD' | 'AI_GEN';
  productPrompt: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

export interface GenerationResult {
  originalUrl: string;
