/**
 * 核心背景替换 - 2+1 差异化逻辑
 */
export const replaceBackground = async (
  base64Image: string,
  environment: EnvironmentType,
  style: SceneStyle,
  customPrompt: string,
  taskType: 'MAIN_A' | 'MAIN_B' | 'DETAIL',
  isPro: boolean = false,
  size: ImageSize = ImageSize.SIZE_1K,
  addReference: boolean = false,
  cleanProduct: boolean = false
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  const modelName = isPro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

  const envPrompts: Record<string, string> = {
    [EnvironmentType.BEDROOM]: "in a high-end luxury bedroom, on a clean wooden bedside stand.",
    [EnvironmentType.DINING_ROOM]: "on an elegant dining table with subtle kitchenware in the background.",
    [EnvironmentType.OUTDOOR_PICNIC]: "in a sun-drenched outdoor garden, on a rustic linen fabric.",
    [EnvironmentType.BATHROOM]: "on a polished marble vanity in a modern minimalist bathroom.",
    [EnvironmentType.LIVING_ROOM]: "on a designer coffee table in a bright architectural living space.",
    [EnvironmentType.OFFICE]: "on a professional mahogany desk in a corporate executive suite.",
    [EnvironmentType.STUDIO]: "in a high-end commercial studio with clean color-graded cyclorama.",
    [EnvironmentType.CAFE]: "on a small bistro table in a trendy boutique cafe."
  };

  const stylePrompts: Record<string, string> = {
    [SceneStyle.MODERN_LUXURY]: "Premium luxury, high-end materials, glossy finishes, rich reflections.",
    [SceneStyle.ZEN_MINIMALIST]: "Serene, natural wood and stone, soft neutral tones, minimalist composition.",
    [SceneStyle.C4D_GEOMETRIC]: "Octane render aesthetic, geometric primitives, clean abstract lighting.",
    [SceneStyle.WINDOW_LIGHT]: "Dramatic natural sunlight through shutters, casting elongated soft shadows.",
    [SceneStyle.WARM_BOKEH]: "Golden hour glow, heavy background bokeh, cozy atmospheric light.",
    [SceneStyle.BLACK_GOLD]: "Stealth luxury, dark stone textures, sharp golden rim lighting.",
    [SceneStyle.CHAOZHOU_RETRO]: "Heritage vintage film look, traditional textures, warm nostalgic grade."
  };

  // 差异化光影逻辑 (Variety Injection)
  let lightModifier = "";
  if (taskType === 'MAIN_A') {
    lightModifier = "LIGHTING: Dynamic side-lighting with high contrast to emphasize product edges and form.";
  } else if (taskType === 'MAIN_B') {
    lightModifier = "LIGHTING: Soft, wrap-around diffused lighting for a clean, balanced commercial look.";
  } else {
    lightModifier = "LIGHTING: Targeted spot lighting to highlight surface textures and material quality.";
  }

  // 参照物逻辑 (仅主图使用)
  const referenceMap: Record<string, string> = {
    [EnvironmentType.BEDROOM]: "a blurry small lamp", [EnvironmentType.DINING_ROOM]: "a blurry wine glass",
    [EnvironmentType.OUTDOOR_PICNIC]: "blurry flowers", [EnvironmentType.BATHROOM]: "a small soap bottle",
    [EnvironmentType.LIVING_ROOM]: "a blurry remote", [EnvironmentType.OFFICE]: "a blurry pen",
    [EnvironmentType.STUDIO]: "blurred studio equipment", [EnvironmentType.CAFE]: "a blurry coffee cup"
  };
  const referencePrompt = (addReference && taskType !== 'DETAIL') 
    ? `SCALE: Include ${referenceMap[environment] || "a lifestyle object"} out-of-focus in background for scale.`
    : "";

  const cleaningPrompt = cleanProduct 
    ? "RETOUCHING: Digitally clean dust/smudges. Ensure product looks PRISTINE while preserving original MATERIAL grain."
    : "";

  const finalPrompt = `
    TASK: ${taskType === 'DETAIL' ? 'MACRO TEXTURE FOCUS' : 'COMMERCIAL LIFESTYLE PHOTOGRAPHY'}.

    ${getPhysicalMaterialBlock(taskType === 'DETAIL')}

    ${lightModifier}

    ENVIRONMENT: The product is ${envPrompts[environment]}.
    STYLE: ${stylePrompts[style]}.
    ${referencePrompt}
    ${cleaningPrompt}
    USER_DETAILS: ${customPrompt}

    INTEGRATION: Perfect light-wrapping and contact shadows. 8k resolution.
    CRITICAL: ${taskType === 'DETAIL' ? 'Focus purely on the MATERIAL TEXTURE of the product. The background should be extremely blurred.' : 'Ensure the product is perfectly integrated into the scene.'}
  `;

  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Image.includes(',') ? base64Image.split(',')[1] : base64Image,
    },
  };

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [imagePart, { text: finalPrompt }] },
    config: isPro ? {
      imageConfig: { aspectRatio: "1:1", imageSize: size }
    } : undefined
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("生成失败");
};

import React, { useState, useRef } from 'react';
import { 
  Upload, 
  Sparkles, 
  Download, 
  MessageSquare, 
  X, 
  ChevronRight,
  RefreshCw,
  LayoutGrid,
  Box,
  CheckCircle2,
  Check,
  Zap,
  Layers,
  Camera,
  Focus
} from 'lucide-react';
import { SceneStyle, EnvironmentType, ImageSize, GenerationConfig, ChatMessage, GenerationResult } from './types';
import { replaceBackground, generateOriginalProduct } from './geminiService';
import { GoogleGenAI, GenerateContentResponse } from '@google/genai';

const App: React.FC = () => {
  const [selectedFile, setSelectedFile] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);

  const [config, setConfig] = useState<GenerationConfig>({
    environment: EnvironmentType.DINING_ROOM,
    style: SceneStyle.WINDOW_LIGHT,
    customPrompt: '',
    isPro: false,
    size: ImageSize.SIZE_1K,
    addReference: true,
    cleanProduct: true,
    mode: 'UPLOAD',
    productPrompt: '一套极简主义风格的白色骨瓷茶具'
  });

  const [showChat, setShowChat] = useState(false);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isChatting, setIsChatting] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setSelectedFile(event.target?.result as string);
        setResult(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    setIsProcessing(true);
    try {
      let baseImage = selectedFile;

      if (config.mode === 'AI_GEN') {
        baseImage = await generateOriginalProduct(config.productPrompt, config.size, config.isPro);
        setSelectedFile(baseImage);
      }

      if (!baseImage) {
        alert("请先上传图片或描述产品");
        setIsProcessing(false);
        return;
      }

      // 执行 2+1 结构化生成
      const tasks = [
        { type: 'MAIN_A' as const, label: '主视觉 · 动态光影' },
        { type: 'MAIN_B' as const, label: '氛围图 · 平衡光效' },
        { type: 'DETAIL' as const, label: '局部特写 · 材质保真' }
      ];

      const promises = tasks.map(task => 
        replaceBackground(
          baseImage!,
          config.environment,
          config.style,
          config.customPrompt,
          task.type,
          config.isPro,
          config.size,
          config.addReference,
          config.cleanProduct
        ).then(url => ({ url, ...task }))
      );

      const generatedImages = await Promise.all(promises);

      setResult({
        originalUrl: baseImage,
        results: generatedImages,
        id: Date.now().toString()
      });
    } catch (error: any) {
      console.error("生成失败:", error);
      alert(`生成失败: ${error.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSendMessage = async () => {
    if (!chatInput.trim()) return;
    const userMsg: ChatMessage = { role: 'user', text: chatInput };
    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatting(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: { systemInstruction: "你是一位资深商业摄影总监。专注于物理材质真实度。请用中文回答。" }
      });
      const response: GenerateContentResponse = await chat.sendMessage({ message: chatInput });
      const modelMsg: ChatMessage = { role: 'model', text: response.text || '抱歉，暂时无法回答。' };
      setChatMessages(prev => [...prev, modelMsg]);
    } catch (error) {
      console.error("对话错误:", error);
    } finally {
      setIsChatting(false);
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#080808] text-white selection:bg-indigo-500/30 font-sans">
      <aside className="w-full md:w-[400px] border-r border-white/5 bg-[#0c0c0c] p-8 flex flex-col gap-6 overflow-y-auto">
        <header className="flex items-center gap-4 mb-2">
          <div className="p-2.5 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-2xl shadow-lg">
            <Sparkles className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="font-bold text-xl tracking-tight">崇正视觉 PRO</h1>
            <p className="text-[10px] text-white/30 uppercase tracking-[0.2em]">2+1 High-Fidelity Engine</p>
          </div>
        </header>

        <section className="bg-white/5 p-1 rounded-2xl flex gap-1">
          <button 
            onClick={() => setConfig({...config, mode: 'UPLOAD'})}
            className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all ${config.mode === 'UPLOAD' ? 'bg-indigo-600 text-white shadow-lg' : 'text-white/40 hover:text-white/60'}`}
          >实拍上传</button>
          <button 
            onClick={() => setConfig({...config, mode: 'AI_GEN'})}
            className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all ${config.mode === 'AI_GEN' ? 'bg-indigo-600 text-white shadow-lg' : 'text-white/40 hover:text-white/60'}`}
          >AI 创作</button>
        </section>

        <div className="space-y-2">
          <label className="text-[10px] font-black text-white/40 uppercase tracking-widest ml-1">高保真渲染控制</label>
          <div className="grid grid-cols-2 gap-2">
             <button 
               onClick={() => setConfig({...config, cleanProduct: !config.cleanProduct})}
               className={`flex items-center justify-between px-4 py-3 rounded-2xl text-[11px] font-bold border transition-all ${config.cleanProduct ? 'bg-indigo-600/10 border-indigo-500/50 text-indigo-400' : 'bg-white/[0.02] border-white/5 text-white/30'}`}
             >
               专业修图
               {config.cleanProduct ? <Check className="w-3 h-3" /> : <Layers className="w-3 h-3 opacity-20" />}
             </button>
             <button 
               onClick={() => setConfig({...config, addReference: !config.addReference})}
               className={`flex items-center justify-between px-4 py-3 rounded-2xl text-[11px] font-bold border transition-all ${config.addReference ? 'bg-indigo-600/10 border-indigo-500/50 text-indigo-400' : 'bg-white/[0.02] border-white/5 text-white/30'}`}
             >
               场景参照
               {config.addReference ? <Check className="w-3 h-3" /> : <Box className="w-3 h-3 opacity-20" />}
             </button>
          </div>
        </div>

        <section className="bg-indigo-600/10 border border-indigo-500/20 p-4 rounded-2xl space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Zap className={`w-4 h-4 ${config.isPro ? 'text-indigo-400' : 'text-white/20'}`} />
              <span className="text-xs font-bold">Pro 级物理渲染</span>
            </div>
            <button 
              onClick={() => setConfig({...config, isPro: !config.isPro})}
              className={`w-10 h-5 rounded-full relative transition-all ${config.isPro ? 'bg-indigo-600' : 'bg-white/10'}`}
            >
              <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${config.isPro ? 'left-6' : 'left-1'}`} />
            </button>
          </div>
          <p className="text-[10px] text-white/40 leading-relaxed italic">开启后将解锁 4K 采样与物理光影包裹。</p>
        </section>

        {config.mode === 'UPLOAD' ? (
          <section className="space-y-4">
            <div className="flex items-center gap-2">
               <Upload className="w-3 h-3 text-indigo-400" />
               <label className="text-[10px] font-black text-white/40 uppercase tracking-widest">产品原图</label>
            </div>
            <div className={`relative group cursor-pointer border-2 border-dashed ${selectedFile ? 'border-indigo-500/50 bg-indigo-500/5' : 'border-white/5 bg-white/[0.02]'} rounded-3xl aspect-square flex items-center justify-center overflow-hidden transition-all`}>
              {selectedFile ? (
                <img src={selectedFile} alt="Preview" className="w-full h-full object-contain p-4" />
              ) : (
                <div className="text-center p-6"><Upload className="w-8 h-8 text-white/20 mx-auto mb-2" /></div>
              )}
              <input type="file" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" />
            </div>
          </section>
        ) : (
          <section className="space-y-4">
            <div className="flex items-center gap-2">
               <Box className="w-3 h-3 text-indigo-400" />
               <label className="text-[10px] font-black text-white/40 uppercase tracking-widest">产品描述</label>
            </div>
            <textarea 
              value={config.productPrompt}
              onChange={(e) => setConfig({...config, productPrompt: e.target.value})}
              placeholder="例如：哑光釉面陶瓷杯..."
