          <div className="h-full flex flex-col items-center justify-center opacity-20">
             <Camera className="w-16 h-16 mb-6" />
             <p className="tracking-[0.5em] text-xs uppercase font-bold text-center">Ready for Multi-View Generation</p>
          </div>
        )}

        {isProcessing && (
          <div className="h-full flex flex-col items-center justify-center space-y-8 animate-in fade-in">
             <div className="relative">
                <div className="w-24 h-24 border-2 border-indigo-500/20 rounded-full animate-ping" />
                <Sparkles className="w-8 h-8 text-indigo-500 absolute inset-0 m-auto animate-pulse" />
             </div>
             <div className="text-center space-y-3">
                <p className="text-sm text-white/70 font-bold tracking-widest uppercase">执行 2+1 结构化渲染任务...</p>
                <p className="text-[10px] text-white/20 uppercase tracking-widest">分离材质物理包 · 注入光影差异种子</p>
             </div>
          </div>
        )}

        {result && !isProcessing && (
          <div className="space-y-12 animate-in fade-in duration-1000">
            <section className="flex items-center gap-8 bg-white/[0.02] p-6 rounded-[32px] border border-white/5">
              <div className="w-32 h-32 rounded-2xl overflow-hidden border border-white/10 flex-shrink-0 bg-black/40 shadow-inner">
                <img src={result.originalUrl} alt="Original" className="w-full h-full object-contain p-2" />
              </div>
              <div>
                <div className="flex items-center gap-2 text-indigo-400 mb-1">
                  <CheckCircle2 className="w-4 h-4" />
                  <span className="text-xs font-bold uppercase tracking-wider">多维度渲染已就绪</span>
                </div>
                <h2 className="text-xl font-bold">主图与材质特写</h2>
                <p className="text-xs text-white/30 mt-1">系统已自动区分视角与材质重点</p>
              </div>
            </section>

            <section className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-8 pb-20">
              {result.results.map((res, index) => (
                <div key={index} className="group relative rounded-[48px] overflow-hidden bg-white/5 border border-white/10 aspect-square shadow-2xl transition-all hover:scale-[1.01] hover:border-indigo-500/30">
                  <img src={res.url} alt={res.label} className="w-full h-full object-cover" />

                  {/* 类型标签 */}
                  <div className="absolute top-6 left-6 flex items-center gap-2 bg-black/60 backdrop-blur-xl px-4 py-2 rounded-full border border-white/10">
                    {res.type === 'DETAIL' ? <Focus className="w-3 h-3 text-purple-400" /> : <Camera className="w-3 h-3 text-indigo-400" />}
                    <span className="text-[10px] font-black uppercase tracking-widest text-white/80">{res.label}</span>
                  </div>

                  <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all duration-500 flex flex-col justify-end p-10">
                    <button 
                      onClick={() => {
                        const link = document.createElement('a');
                        link.href = res.url;
                        link.download = `lumina-${res.type}-${index+1}.png`;
                        link.click();
                      }}
                      className="w-full bg-white text-black py-4 rounded-2xl font-bold text-xs flex items-center justify-center gap-2 hover:bg-indigo-50 active:scale-95 transition-all shadow-xl"
                    >
                      <Download className="w-4 h-4" /> 下载高保真原片
                    </button>
                  </div>
                </div>
              ))}
            </section>
          </div>
        )}

        {/* 聊天入口 */}
        <button 
          onClick={() => setShowChat(!showChat)}
          className={`fixed bottom-10 right-10 p-5 rounded-3xl shadow-2xl z-50 transition-all ${showChat ? 'bg-red-500 rotate-90' : 'bg-indigo-600 hover:scale-110'}`}
        >
          {showChat ? <X /> : <MessageSquare />}
        </button>

        {showChat && (
          <div className="fixed bottom-32 right-10 w-80 md:w-[400px] h-[550px] bg-[#121212] border border-white/10 rounded-[40px] shadow-2xl flex flex-col z-50 overflow-hidden animate-in slide-in-from-bottom-10">
             <header className="p-6 border-b border-white/5 bg-white/[0.02] flex items-center justify-between">
                <span className="text-xs font-bold tracking-widest uppercase opacity-60">视觉总监诊断室</span>
                <button onClick={() => setShowChat(false)} className="opacity-20 hover:opacity-100 transition-opacity"><X className="w-4 h-4" /></button>
             </header>
             <div className="flex-1 overflow-y-auto p-6 space-y-6">
                {chatMessages.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                     <div className={`max-w-[85%] px-5 py-3 rounded-2xl text-[13px] leading-relaxed ${msg.role === 'user' ? 'bg-indigo-600 text-white' : 'bg-white/5 border border-white/10 text-white/80'}`}>
                        {msg.text}
                     </div>
                  </div>
                ))}
                {isChatting && <div className="text-[10px] text-white/20 animate-pulse ml-2 uppercase font-bold">Analyzing...</div>}
                <div ref={chatEndRef} />
             </div>
             <div className="p-6 border-t border-white/5">
                <div className="flex gap-3">
                   <input 
                     type="text" 
                     value={chatInput} 
                     onChange={e => setChatInput(e.target.value)}
                     onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
                     placeholder="关于材质保真的建议..." 
                     className="flex-1 bg-black/40 border border-white/10 rounded-2xl px-5 py-3 text-sm focus:outline-none focus:ring-1 focus:ring-indigo-500"
                   />
                   <button onClick={handleSendMessage} className="w-12 h-12 flex items-center justify-center bg-indigo-600 rounded-2xl shadow-lg"><ChevronRight /></button>
                </div>
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

