        replaceBackground(
          baseImage!,
          config.environment,
          config.style,
          config.customPrompt,
          task.type,
          config.isPro,
          config.size,
          config.addReference,
          config.cleanProduct
        ).then(url => ({ url, type: task.type, label: task.label, description: task.desc }))
