                      className="w-full bg-white text-black py-4 rounded-2xl font-bold text-xs flex items-center justify-center gap-2 hover:bg-indigo-50 active:scale-95 transition-all"
                    >
                      <Download className="w-4 h-4" /> 下载 4K 原片
