          </div>
        )}

        <button 
          onClick={() => setShowChat(!showChat)}
          className={`fixed bottom-10 right-10 p-5 rounded-3xl shadow-2xl z-50 transition-all ${showChat ? 'bg-red-500 rotate-90' : 'bg-indigo-600 hover:scale-110'}`}
        >
          {showChat ? <X /> : <MessageSquare />}
        </button>

        {showChat && (
          <div className="fixed bottom-32 right-10 w-80 md:w-[400px] h-[550px] bg-[#121212] border border-white/10 rounded-[40px] shadow-2xl flex flex-col z-50 overflow-hidden animate-in slide-in-from-bottom-10">
             <header className="p-6 border-b border-white/5 bg-white/[0.02] flex items-center justify-between">
                <span className="text-xs font-bold tracking-widest uppercase opacity-60">视觉总监诊断室</span>
                <button onClick={() => setShowChat(false)} className="opacity-20 hover:opacity-100 transition-opacity"><X className="w-4 h-4" /></button>
             </header>
             <div className="flex-1 overflow-y-auto p-6 space-y-6">
                {chatMessages.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                     <div className={`max-w-[85%] px-5 py-3 rounded-2xl text-[13px] leading-relaxed ${msg.role === 'user' ? 'bg-indigo-600 text-white' : 'bg-white/5 border border-white/10 text-white/80'}`}>
                        {msg.text}
                     </div>
                  </div>
                ))}
                {isChatting && <div className="text-[10px] text-white/20 animate-pulse ml-2 uppercase font-bold">Analyzing...</div>}
                <div ref={chatEndRef} />
             </div>
             <div className="p-6 border-t border-white/5">
                <div className="flex gap-3">
                   <input 
                     type="text" 
                     value={chatInput} 
                     onChange={e => setChatInput(e.target.value)}
                     onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
                     placeholder="询问关于构图或光影的建议..." 
                     className="flex-1 bg-black/40 border border-white/10 rounded-2xl px-5 py-3 text-sm focus:outline-none focus:ring-1 focus:ring-indigo-500"
                   />
                   <button onClick={handleSendMessage} className="w-12 h-12 flex items-center justify-center bg-indigo-600 rounded-2xl shadow-lg"><ChevronRight /></button>
                </div>
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { SceneStyle, EnvironmentType, ImageSize, ImageTaskType } from "./types";

const getAIClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

/**
 * 核心保真协议 - 永远作为第一优先级
 */
const getStrictIdentityProtocol = () => `
[STRICT IDENTITY PROTOCOL]
- RETAIN the product's exact physical form, dimensions, and texture.
- NO DEFORMATION: The product must not bend, stretch, or warp to match the background.
- AUTHENTICITY: Ensure the product looks like a real physical object, not a drawing.
`;

export const generateOriginalProduct = async (
  productDescription: string,
  size: ImageSize = ImageSize.SIZE_1K,
  usePro: boolean = false
): Promise<string> => {
  const ai = getAIClient();
  const modelName = usePro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';
  const prompt = `TASK: PROFESSIONAL PRODUCT PHOTOGRAPHY. SUBJECT: ${productDescription}. STYLE: Studio white background, clean lighting, 8k.`;
  const response: GenerateContentResponse = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [{ text: prompt }] },
    config: usePro ? { imageConfig: { aspectRatio: "1:1", imageSize: size } } : undefined
  });
  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
  }
  throw new Error("生成失败");
};

export const replaceBackground = async (
  base64Image: string,
  environment: EnvironmentType,
  style: SceneStyle,
  customPrompt: string,
  taskType: ImageTaskType,
  isPro: boolean = false,
  size: ImageSize = ImageSize.SIZE_1K,
  addReference: boolean = false,
  cleanProduct: boolean = false
): Promise<string> => {
  const ai = getAIClient();
  const modelName = isPro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

  // 基础 DNA 库
  const envPrompts: Record<string, string> = {
    [EnvironmentType.BEDROOM]: "a high-end luxury bedroom",
    [EnvironmentType.DINING_ROOM]: "an elegant dining room",
    [EnvironmentType.OUTDOOR_PICNIC]: "a sunny outdoor garden",
    [EnvironmentType.BATHROOM]: "a modern marble bathroom",
    [EnvironmentType.LIVING_ROOM]: "a designer living room",
    [EnvironmentType.OFFICE]: "a professional minimalist office",
    [EnvironmentType.STUDIO]: "a clean photography studio",
    [EnvironmentType.CAFE]: "a boutique urban cafe"
  };

  const stylePrompts: Record<string, string> = {
    [SceneStyle.MODERN_LUXURY]: "Premium luxury, marble, gold accents, clean sharp lighting.",
    [SceneStyle.ZEN_MINIMALIST]: "Peaceful, organic textures, wood, stone, diffused lighting.",
    [SceneStyle.C4D_GEOMETRIC]: "Avant-garde 3D render style, abstract shapes, soft pastel colors.",
    [SceneStyle.WINDOW_LIGHT]: "Cinematic window light, soft ray tracing, airy atmosphere.",
    [SceneStyle.WARM_BOKEH]: "Warm cozy evening mood, rich bokeh, lens flare.",
    [SceneStyle.BLACK_GOLD]: "Sultry dark mode, black slate, dramatic rim lighting.",
    [SceneStyle.CHAOZHOU_RETRO]: "Southern Chinese vintage textures, nostalgic architecture."
  };

  /**
   * 动态任务权重分配逻辑
   */
  let taskFocus = "";
  let environmentPriority = "NORMAL";

  switch (taskType) {
    case 'DETAIL':
      // 细节图：极高材质权重，极低环境权重
      environmentPriority = "LOW";
      taskFocus = `
        [TASK: MACRO MATERIAL FOCUS]
        - ZOOM: Extreme macro close-up on the product's surface texture.
        - COMPOSITION: Abstract close-up. 
        - BACKGROUND: The ${envPrompts[environment]} should be purely abstract colors and extreme bokeh. Do NOT show furniture or room details.
        - LIGHTING: Focus on revealing micro-textures (glaze, fabric, metal grain).
      `;
      break;
    case 'AD_POSTER':
      // 海报图：中等材质权重，高构图/光影权重
      environmentPriority = "MEDIUM";
      taskFocus = `
        [TASK: DRAMATIC COMMERCIAL POSTER]
        - COMPOSITION: Hero-shot. Use dramatic lighting and shadows.
        - FEEL: High-end magazine advertisement style. 
        - ATMOSPHERE: Prioritize the ${stylePrompts[style]} feel over realistic furniture placement.
      `;
      break;
    case 'AD_NEGATIVE':
      // 留白广告：功能性构图权重
      environmentPriority = "NORMAL";
      taskFocus = `
        [TASK: NEGATIVE SPACE AD]
        - COMPOSITION: Rule of thirds. Move product to the side. 
        - COPY_SPACE: Leave significant empty space in the background for text.
        - CONTEXT: Seamlessly integrate with ${envPrompts[environment]}.
      `;
      break;
    case 'LIFESTYLE':
      // 使用图：高环境权重，高融合权重
      environmentPriority = "HIGH";
      taskFocus = `
        [TASK: AUTHENTIC LIFESTYLE]
        - SCENE: The product must feel "at home" in the ${envPrompts[environment]}.
        - ANGLE: Natural human-eye perspective. 
        - INTERACTION: Show realistic contact with the surface.
      `;
      break;
    default: // MAIN_A, MAIN_B
      environmentPriority = "NORMAL";
      taskFocus = `
        [TASK: PREMIUM MAIN VIEW]
        - VIEW: Iconic, clear, and perfectly lit commercial shot.
        - INTEGRATION: Professional studio-level integration with ${envPrompts[environment]}.
      `;
  }

  const cleaning = cleanProduct ? "CLEANING: Digitally remove any dust or fingerprints from the product." : "";
  const ref = (addReference && environmentPriority !== "LOW") ? "SCALE: Add a subtle blurry object nearby for scale." : "";

  // 组装最终提示词，根据优先级调整描述顺序
  const finalPrompt = `
    ${getStrictIdentityProtocol()}

    ${taskFocus}

    ${environmentPriority !== "LOW" ? `ENVIRONMENT: Set in ${envPrompts[environment]}.` : ""}
    VISUAL STYLE: ${stylePrompts[style]}

    ${cleaning}
    ${ref}
    ${customPrompt ? `CLIENT_REQUEST: ${customPrompt}` : ""}

    QUALITY: Photorealistic, 8k, professional grade. FINAL REMINDER: DO NOT DEFORM THE PRODUCT.
  `;

  const response = await ai.models.generateContent({
    model: modelName,
    contents: { 
      parts: [
        { inlineData: { mimeType: 'image/jpeg', data: base64Image.split(',')[1] || base64Image } }, 
        { text: finalPrompt }
      ] 
    },
    config: isPro ? { imageConfig: { aspectRatio: "1:1", imageSize: size } } : undefined
  });

  const base64 = response.candidates?.[0]?.content?.parts.find(p => p.inlineData)?.inlineData?.data;
  if (!base64) throw new Error("AI未能生成图像");
  return `data:image/png;base64,${base64}`;
};

export enum EnvironmentType {
