import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { SceneStyle, EnvironmentType, ImageSize, ImageTaskType } from "./types";

const getAIClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

/**
 * 核心保真协议
 */
const getStrictIdentityProtocol = () => `
[STRICT IDENTITY PROTOCOL]
- RETAIN the product's exact physical form, dimensions, and texture.
- NO DEFORMATION: The product must not bend, stretch, or warp.
- PERSPECTIVE ALIGNMENT: Adjust the perspective of the product to match the specified camera angle perfectly.
`;

/**
 * 随机生成一个专业的产品描述词
 */
export const generateRandomProductPrompt = async (): Promise<string> => {
  const ai = getAIClient();
  const prompt = `
    作为一名资深电商摄影师，请随机提供一个高端、极简的产品描述词。
    要求：
    1. 仅包含产品名称、材质和核心造型特征。
    2. 语言极其简约（不超过20个字）。
    3. 适合作为 AI 图像生成的 Prompt。
    4. 例如：“手工拉坯的粗陶茶杯，亚光黑色釉面”、“极简不锈钢咖啡手冲壶，流线型设计”。
    直接返回描述词，不要包含任何解释或引号。
  `;

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [{ parts: [{ text: prompt }] }],
    config: {
      temperature: 0.9,
      topK: 40,
    }
  });

  return response.text.trim() || "一套极简主义风格的白色骨瓷茶具";
};

export const generateOriginalProduct = async (
  productDescription: string,
  size: ImageSize = ImageSize.SIZE_1K,
  usePro: boolean = false
): Promise<string> => {
  const ai = getAIClient();
  const modelName = usePro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';
  const prompt = `TASK: PROFESSIONAL PRODUCT PHOTOGRAPHY. SUBJECT: ${productDescription}. STYLE: Studio white background, clean lighting.`;
  const response: GenerateContentResponse = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [{ text: prompt }] },
    config: usePro ? { imageConfig: { aspectRatio: "1:1", imageSize: size } } : undefined
  });
  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
  }
  throw new Error("生成失败");
};

export const replaceBackground = async (
  base64Image: string,
  environment: EnvironmentType,
  style: SceneStyle,
  customPrompt: string,
  taskType: ImageTaskType,
  isPro: boolean = false,
  size: ImageSize = ImageSize.SIZE_1K,
  addReference: boolean = false,
  cleanProduct: boolean = false
): Promise<string> => {
  const ai = getAIClient();
  const modelName = isPro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

  const envPrompts: Record<string, string> = {
    [EnvironmentType.BEDROOM]: "a high-end luxury bedroom",
    [EnvironmentType.DINING_ROOM]: "an elegant dining room",
    [EnvironmentType.OUTDOOR_PICNIC]: "a sunny outdoor garden",
    [EnvironmentType.BATHROOM]: "a modern marble bathroom",
    [EnvironmentType.LIVING_ROOM]: "a designer living room",
    [EnvironmentType.OFFICE]: "a professional minimalist office",
    [EnvironmentType.STUDIO]: "a clean photography studio",
    [EnvironmentType.CAFE]: "a boutique urban cafe"
  };

  const stylePrompts: Record<string, string> = {
    [SceneStyle.MODERN_LUXURY]: "Premium luxury, marble, gold accents, clean sharp lighting.",
    [SceneStyle.ZEN_MINIMALIST]: "Peaceful, organic textures, wood, stone, diffused lighting.",
    [SceneStyle.C4D_GEOMETRIC]: "Avant-garde 3D render style, abstract shapes, soft pastel colors.",
    [SceneStyle.WINDOW_LIGHT]: "Cinematic window light, soft ray tracing, airy atmosphere.",
    [SceneStyle.WARM_BOKEH]: "Warm cozy evening mood, rich bokeh, lens flare.",
    [SceneStyle.BLACK_GOLD]: "Sultry dark mode, black slate, dramatic rim lighting.",
    [SceneStyle.CHAOZHOU_RETRO]: "Southern Chinese vintage textures, nostalgic architecture."
  };

  let taskInstruction = "";
  let envWeight = "NORMAL";

  switch (taskType) {
    case 'VIEW_TOP':
      taskInstruction = `
        [TASK: TOP-DOWN VIEW]
        - CAMERA: Flat lay, looking straight down from above the product.
        - ANGLE: 90-degree vertical perspective.
        - FOCUS: Top details and overall footprint.
      `;
      break;
    case 'VIEW_SIDE':
      taskInstruction = `
        [TASK: 45-DEGREE PROFILE VIEW]
        - CAMERA: Three-quarter view from the side.
        - ANGLE: Emphasize the depth, volume, and side-profile of the product.
        - DEPTH: Show the side texture and geometric complexity.
      `;
      break;
    case 'DETAIL_MACRO':
      envWeight = "LOW";
      taskInstruction = `
        [TASK: MACRO MATERIAL FOCUS]
        - ZOOM: Extreme macro close-up. Focus purely on surface texture.
        - BACKGROUND: Extreme bokeh. Abstract colors only.
      `;
      break;
    case 'AD_POSTER':
      taskInstruction = `
        [TASK: HEROIC AD VIEW]
        - CAMERA: Low-angle shot, looking slightly upward.
        - FEEL: Majestic, grand commercial aesthetic.
        - LIGHTING: High-contrast, rim lighting.
      `;
      break;
    case 'AD_NEGATIVE':
      taskInstruction = `
        [TASK: COMPOSITIONAL NEGATIVE SPACE]
        - COMPOSITION: Rule of thirds. Product is positioned at the far left or right.
        - PURPOSE: Leave large empty area for advertising copy.
      `;
      break;
    default: // FRONT_HERO
      taskInstruction = `
        [TASK: ICONIC FRONT VIEW]
        - CAMERA: Straight-on eye-level view.
        - PURPOSE: Standard catalog primary image.
      `;
  }

  const cleanCmd = cleanProduct ? "RETCH: Ensure the product surface is pristine and clean." : "";
  const refCmd = (addReference && envWeight !== "LOW") ? "SCALE: Add a subtle blurry household object for size comparison." : "";

  const finalPrompt = `
    ${getStrictIdentityProtocol()}
    ${taskInstruction}
    ${envWeight !== "LOW" ? `ENVIRONMENT: In ${envPrompts[environment]}.` : ""}
    VISUAL STYLE: ${stylePrompts[style]}
    ${cleanCmd}
    ${refCmd}
    ${customPrompt ? `EXTRA_DETAIL: ${customPrompt}` : ""}
    PHOTOGRAPHY: Photorealistic, 8k, sharp focus on product.
  `;

  const response = await ai.models.generateContent({
    model: modelName,
    contents: [{ parts: [{ inlineData: { mimeType: 'image/jpeg', data: base64Image.split(',')[1] || base64Image } }, { text: finalPrompt }] }],
    config: isPro ? { imageConfig: { aspectRatio: "1:1", imageSize: size } } : undefined
  });

  const base64 = response.candidates?.[0]?.content?.parts.find(p => p.inlineData)?.inlineData?.data;
  if (!base64) throw new Error("AI未能生成图像");
  return `data:image/png;base64,${base64}`;
};

import React, { useState, useRef } from 'react';
import { 
  Upload, 
  Sparkles, 
  Download, 
  MessageSquare, 
  X, 
  ChevronRight,
  RefreshCw,
  LayoutGrid,
  Box,
  Check,
  Zap,
  Layers,
  Camera,
  Focus,
  Trophy,
  Image as ImageIcon,
  Compass,
  ArrowDownCircle,
  Maximize2,
  Dices
} from 'lucide-react';
import { SceneStyle, EnvironmentType, ImageSize, GenerationConfig, ChatMessage, GenerationResult, ImageTaskType } from './types';
import { replaceBackground, generateOriginalProduct, generateRandomProductPrompt } from './geminiService';
import { GoogleGenAI, GenerateContentResponse } from '@google/genai';

const App: React.FC = () => {
  const [selectedFile, setSelectedFile] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isGeneratingPrompt, setIsGeneratingPrompt] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);

  const [config, setConfig] = useState<GenerationConfig>({
    environment: EnvironmentType.DINING_ROOM,
    style: SceneStyle.WINDOW_LIGHT,
    customPrompt: '',
    isPro: false,
    size: ImageSize.SIZE_1K,
    addReference: true,
    cleanProduct: true,
    mode: 'UPLOAD',
    productPrompt: '一套极简主义风格的白色骨瓷茶具',
    plan: 'BASIC'
  });

  const [showChat, setShowChat] = useState(false);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isChatting, setIsChatting] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setSelectedFile(event.target?.result as string);
        setResult(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleRandomPrompt = async () => {
    setIsGeneratingPrompt(true);
    try {
      const randomPrompt = await generateRandomProductPrompt();
      setConfig(prev => ({ ...prev, productPrompt: randomPrompt }));
    } catch (error) {
      console.error("生成灵感失败:", error);
    } finally {
      setIsGeneratingPrompt(false);
    }
  };

  const handleGenerate = async () => {
    setIsProcessing(true);
    try {
      let baseImage = selectedFile;
      if (config.mode === 'AI_GEN') {
        baseImage = await generateOriginalProduct(config.productPrompt, config.size, config.isPro);
        setSelectedFile(baseImage);
      }
      if (!baseImage) {
        alert("请先上传图片或描述产品");
        setIsProcessing(false);
        return;
      }

      const tasks: { type: ImageTaskType; label: string; desc: string }[] = config.plan === 'BASIC' 
        ? [
            { type: 'FRONT_HERO', label: '正面视窗', desc: '标准展示' },
            { type: 'VIEW_SIDE', label: '侧翼轮廓', desc: '深度展示' },
            { type: 'DETAIL_MACRO', label: '微距指纹', desc: '材质展示' }
          ]
        : [
            { type: 'FRONT_HERO', label: '正视角 · 主', desc: '全景呈现' },
            { type: 'VIEW_TOP', label: '俯视角 · 顶', desc: '轮廓呈现' },
            { type: 'VIEW_SIDE', label: '45°侧视角', desc: '立体呈现' },
            { type: 'DETAIL_MACRO', label: '极微距 · 质', desc: '触感呈现' },
            { type: 'AD_POSTER', label: '英雄仰视角', desc: '张力呈现' },
            { type: 'AD_NEGATIVE', label: '黄金分割视角', desc: '商业留白' }
          ];

      const promises = tasks.map(task => 
        replaceBackground(
          baseImage!,
          config.environment,
          config.style,
          config.customPrompt,
          task.type,
          config.isPro,
          config.size,
          config.addReference,
          config.cleanProduct
        ).then(url => ({ url, type: task.type, label: task.label, description: task.desc }))
      );

      const generatedImages = await Promise.all(promises);

      setResult({
        originalUrl: baseImage,
        results: generatedImages,
        id: Date.now().toString()
      });
    } catch (error: any) {
      console.error("生成失败:", error);
      alert(`生成失败: ${error.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSendMessage = async () => {
    if (!chatInput.trim()) return;
    const userMsg: ChatMessage = { role: 'user', text: chatInput };
    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatting(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: { systemInstruction: "你是一位资深商业摄影总监。专注于视角、光影和材质。请用中文回答。" }
      });
      const response: GenerateContentResponse = await chat.sendMessage({ message: chatInput });
      const modelMsg: ChatMessage = { role: 'model', text: response.text || '抱歉，暂时无法回答。' };
      setChatMessages(prev => [...prev, modelMsg]);
    } catch (error) {
      console.error("对话错误:", error);
    } finally {
      setIsChatting(false);
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#080808] text-white selection:bg-indigo-500/30 font-sans">
      <aside className="w-full md:w-[400px] border-r border-white/5 bg-[#0c0c0c] p-8 flex flex-col gap-6 overflow-y-auto">
        <header className="flex items-center gap-4 mb-2">
          <div className="p-2.5 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-2xl shadow-lg">
            <Sparkles className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="font-bold text-xl tracking-tight">崇正视觉 PRO</h1>
            <p className="text-[10px] text-white/30 uppercase tracking-[0.2em]">High-Fidelity Suite</p>
          </div>
        </header>

        <section className="bg-white/5 p-1 rounded-2xl flex gap-1">
          <button 
            onClick={() => setConfig({...config, plan: 'BASIC'})}
            className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all ${config.plan === 'BASIC' ? 'bg-indigo-600 text-white shadow-lg' : 'text-white/40 hover:text-white/60'}`}
          >标准 2+1</button>
          <button 
            onClick={() => setConfig({...config, plan: 'PRO_SET'})}
            className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all ${config.plan === 'PRO_SET' ? 'bg-indigo-600 text-white shadow-lg' : 'text-white/40 hover:text-white/60'}`}
          >专业 6 视角</button>
        </section>

        <section className="bg-white/5 p-1 rounded-2xl flex gap-1">
          <button 
            onClick={() => setConfig({...config, mode: 'UPLOAD'})}
            className={`flex-1 py-2 rounded-xl text-[10px] font-bold transition-all ${config.mode === 'UPLOAD' ? 'bg-white/10 text-white shadow-sm' : 'text-white/40 hover:text-white/60'}`}
          >实拍上传</button>
          <button 
            onClick={() => setConfig({...config, mode: 'AI_GEN'})}
            className={`flex-1 py-2 rounded-xl text-[10px] font-bold transition-all ${config.mode === 'AI_GEN' ? 'bg-white/10 text-white shadow-sm' : 'text-white/40 hover:text-white/60'}`}
          >AI 创作</button>
        </section>

        <div className="space-y-2">
          <label className="text-[10px] font-black text-white/40 uppercase tracking-widest ml-1">高保真渲染控制</label>
          <div className="grid grid-cols-2 gap-2">
             <button 
               onClick={() => setConfig({...config, cleanProduct: !config.cleanProduct})}
               className={`flex items-center justify-between px-4 py-3 rounded-2xl text-[11px] font-bold border transition-all ${config.cleanProduct ? 'bg-indigo-600/10 border-indigo-500/50 text-indigo-400' : 'bg-white/[0.02] border-white/5 text-white/30'}`}
             >
               精修材质
               {config.cleanProduct ? <Check className="w-3 h-3" /> : <Layers className="w-3 h-3 opacity-20" />}
             </button>
             <button 
               onClick={() => setConfig({...config, addReference: !config.addReference})}
               className={`flex items-center justify-between px-4 py-3 rounded-2xl text-[11px] font-bold border transition-all ${config.addReference ? 'bg-indigo-600/10 border-indigo-500/50 text-indigo-400' : 'bg-white/[0.02] border-white/5 text-white/30'}`}
             >
               空间比例
               {config.addReference ? <Check className="w-3 h-3" /> : <Box className="w-3 h-3 opacity-20" />}
             </button>
          </div>
        </div>

        <section className="bg-indigo-600/10 border border-indigo-500/20 p-4 rounded-2xl space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Zap className={`w-4 h-4 ${config.isPro ? 'text-indigo-400' : 'text-white/20'}`} />
              <span className="text-xs font-bold">Pro 级物理渲染</span>
            </div>
            <button 
              onClick={() => setConfig({...config, isPro: !config.isPro})}
              className={`w-10 h-5 rounded-full relative transition-all ${config.isPro ? 'bg-indigo-600' : 'bg-white/10'}`}
            >
              <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${config.isPro ? 'left-6' : 'left-1'}`} />
            </button>
          </div>
        </section>

        {config.mode === 'UPLOAD' ? (
          <section className="space-y-4">
            <div className={`relative group cursor-pointer border-2 border-dashed ${selectedFile ? 'border-indigo-500/50 bg-indigo-500/5' : 'border-white/5 bg-white/[0.02]'} rounded-3xl aspect-square flex items-center justify-center overflow-hidden transition-all`}>
              {selectedFile ? (
                <img src={selectedFile} alt="Preview" className="w-full h-full object-contain p-4" />
