import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { SceneStyle, EnvironmentType, ImageSize, ImageTaskType } from "./types";

const getAIClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

/**
 * 核心保真协议
 */
const getStrictIdentityProtocol = () => `
[STRICT IDENTITY PROTOCOL]
- RETAIN the product's exact physical form, dimensions, and texture.
- NO DEFORMATION: The product must not bend, stretch, or warp.
- PERSPECTIVE ALIGNMENT: Adjust the perspective of the product to match the specified camera angle perfectly.
`;

/**
 * 随机生成一个专业的产品描述词
 */
export const generateRandomProductPrompt = async (): Promise<string> => {
  const ai = getAIClient();
  const prompt = `
    作为一名资深电商摄影师，请随机提供一个高端、极简的产品描述词。
    要求：
    1. 仅包含产品名称、材质和核心造型特征。
    2. 语言极其简约（不超过20个字）。
    3. 适合作为 AI 图像生成的 Prompt。
    4. 例如：“手工拉坯的粗陶茶杯，亚光黑色釉面”、“极简不锈钢咖啡手冲壶，流线型设计”。
    直接返回描述词，不要包含任何解释或引号。
  `;

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [{ parts: [{ text: prompt }] }],
    config: {
      temperature: 0.9,
      topK: 40,
    }
  });

  return response.text.trim() || "一套极简主义风格的白色骨瓷茶具";
};

export const generateOriginalProduct = async (
  productDescription: string,
  size: ImageSize = ImageSize.SIZE_1K,
  usePro: boolean = false
): Promise<string> => {
  const ai = getAIClient();
  const modelName = usePro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';
  const prompt = `TASK: PROFESSIONAL PRODUCT PHOTOGRAPHY. SUBJECT: ${productDescription}. STYLE: Studio white background, clean lighting.`;
  const response: GenerateContentResponse = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [{ text: prompt }] },
    config: usePro ? { imageConfig: { aspectRatio: "1:1", imageSize: size } } : undefined
  });
  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
  }
  throw new Error("生成失败");
};

export const replaceBackground = async (
  base64Image: string,
  environment: EnvironmentType,
  style: SceneStyle,
  customPrompt: string,
  taskType: ImageTaskType,
  isPro: boolean = false,
  size: ImageSize = ImageSize.SIZE_1K,
  addReference: boolean = false,
  cleanProduct: boolean = false
): Promise<string> => {
  const ai = getAIClient();
  const modelName = isPro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

  const envPrompts: Record<string, string> = {
    [EnvironmentType.PAIFANG_STREET]: "the historic Chaoshan Paifang Street with traditional stone arches and vintage Lingnan architecture",
    [EnvironmentType.BINJIANG_PROMENADE]: "the scenic Chaoshan Binjiang Promenade by the river with ancient city walls and banyan trees",
    [EnvironmentType.PHOENIX_TIANCHI]: "the misty Phoenix Heaven Lake (Fenghuang Tianchi) mountain top surrounded by high-altitude tea plantations and soft clouds",
    [EnvironmentType.GUANGJI_BRIDGE]: "the ancient Guangji Bridge with its iconic wooden pavilions and floating bridge structures",
    [EnvironmentType.BEDROOM]: "a high-end luxury bedroom",
    [EnvironmentType.DINING_ROOM]: "an elegant dining room",
    [EnvironmentType.OUTDOOR_PICNIC]: "a sunny outdoor garden",
    [EnvironmentType.BATHROOM]: "a modern marble bathroom",
    [EnvironmentType.LIVING_ROOM]: "a designer living room",
    [EnvironmentType.OFFICE]: "a professional minimalist office",
    [EnvironmentType.STUDIO]: "a clean photography studio",
    [EnvironmentType.CAFE]: "a boutique urban cafe"
  };

  const stylePrompts: Record<string, string> = {
    [SceneStyle.MODERN_LUXURY]: "Premium luxury, marble, gold accents, clean sharp lighting.",
    [SceneStyle.ZEN_MINIMALIST]: "Peaceful, organic textures, wood, stone, diffused lighting.",
    [SceneStyle.C4D_GEOMETRIC]: "Avant-garde 3D render style, abstract shapes, soft pastel colors.",
    [SceneStyle.WINDOW_LIGHT]: "Cinematic window light, soft ray tracing, airy atmosphere.",
    [SceneStyle.WARM_BOKEH]: "Warm cozy evening mood, rich bokeh, lens flare.",
    [SceneStyle.BLACK_GOLD]: "Sultry dark mode, black slate, dramatic rim lighting.",
    [SceneStyle.CHAOZHOU_RETRO]: "Southern Chinese vintage textures, nostalgic architecture, warm film grain."
  };

  let taskInstruction = "";
  let envWeight = "NORMAL";

  switch (taskType) {
    case 'VIEW_TOP':
      taskInstruction = `
        [TASK: TOP-DOWN VIEW]
        - CAMERA: Flat lay, looking straight down from above the product.
        - ANGLE: 90-degree vertical perspective.
        - FOCUS: Top details and overall footprint.
      `;
      break;
    case 'VIEW_SIDE':
      taskInstruction = `
        [TASK: 45-DEGREE PROFILE VIEW]
        - CAMERA: Three-quarter view from the side.
        - ANGLE: Emphasize the depth, volume, and side-profile of the product.
        - DEPTH: Show the side texture and geometric complexity.
      `;
      break;
    case 'DETAIL_MACRO':
      envWeight = "LOW";
      taskInstruction = `
        [TASK: MACRO MATERIAL FOCUS]
        - ZOOM: Extreme macro close-up. Focus purely on surface texture.
        - BACKGROUND: Extreme bokeh. Abstract colors only.
      `;
      break;
    case 'AD_POSTER':
      taskInstruction = `
        [TASK: HEROIC AD VIEW]
        - CAMERA: Low-angle shot, looking slightly upward.
        - FEEL: Majestic, grand commercial aesthetic.
        - LIGHTING: High-contrast, rim lighting.
      `;
      break;
    case 'AD_NEGATIVE':
      taskInstruction = `
        [TASK: COMPOSITIONAL NEGATIVE SPACE]
        - COMPOSITION: Rule of thirds. Product is positioned at the far left or right.
        - PURPOSE: Leave large empty area for advertising copy.
      `;
      break;
    default: // FRONT_HERO
      taskInstruction = `
        [TASK: ICONIC FRONT VIEW]
        - CAMERA: Straight-on eye-level view.
        - PURPOSE: Standard catalog primary image.
      `;
  }

  const cleanCmd = cleanProduct ? "RETCH: Ensure the product surface is pristine and clean." : "";
  const refCmd = (addReference && envWeight !== "LOW") ? "SCALE: Add a subtle blurry household object for size comparison." : "";

  const finalPrompt = `
    ${getStrictIdentityProtocol()}
    ${taskInstruction}
    ${envWeight !== "LOW" ? `ENVIRONMENT: In ${envPrompts[environment]}.` : ""}
    VISUAL STYLE: ${stylePrompts[style]}
    ${cleanCmd}
    ${refCmd}
    ${customPrompt ? `EXTRA_DETAIL: ${customPrompt}` : ""}
    PHOTOGRAPHY: Photorealistic, 8k, sharp focus on product.
  `;

  const response = await ai.models.generateContent({
    model: modelName,
    contents: [{ parts: [{ inlineData: { mimeType: 'image/jpeg', data: base64Image.split(',')[1] || base64Image } }, { text: finalPrompt }] }],
    config: isPro ? { imageConfig: { aspectRatio: "1:1", imageSize: size } } : undefined
  });

  const base64 = response.candidates?.[0]?.content?.parts.find(p => p.inlineData)?.inlineData?.data;
  if (!base64) throw new Error("AI未能生成图像");
  return `data:image/png;base64,${base64}`;
};
